# ================= ✏️ BITTA XABARDA NAVIGATSIYA (edit-in-place) — BARCHA BOTLAR UCHUN =================
# Inline tugma bosilganda bot yangi xabar tashlamaydi — o'sha xabarning o'zini tahrirlaydi.
# Har bir ochilgan ichki sahifaga avtomatik "⬅️ Orqaga" tugmasi qo'shiladi (oldingi sahifaga qaytaradi).
# Bu asosiy bot, klon botlar va barcha bolalar botlariga (kino, va h.k.) birdek ta'sir qiladi.
from contextvars import ContextVar
from collections import OrderedDict

_EIP_CTX: ContextVar = ContextVar("eip_ctx", default=None)
_EIP_STACKS: "OrderedDict" = OrderedDict()   # (bot_id, chat_id, message_id) -> [oldingi sahifalar]
_EIP_MAX_KEYS = 5000
_EIP_MAX_DEPTH = 25
EIP_BACK_DATA = "eip_back"
EIP_BACK_TEXT = "⬅️ Orqaga"
_EIP_NAV_WORDS = ("orqaga", "ortga", "⬅", "🔙", "◀", "bosh menyu", "bekor", "back")
_EIP_EDIT_KW = {"parse_mode", "entities", "link_preview_options", "disable_web_page_preview", "reply_markup"}
_EIP_IGNORE_KW = {"disable_notification", "protect_content", "allow_sending_without_reply",
                  "message_effect_id", "allow_paid_broadcast"}


def _eip_key(msg):
    bot_obj = getattr(msg, "bot", None)
    return (bot_obj.id if bot_obj is not None else 0, msg.chat.id, msg.message_id)


def _eip_has_nav(markup) -> bool:
    if markup is None:
        return False
    for row in markup.inline_keyboard:
        for b in row:
            t = (b.text or "").lower()
            d = (getattr(b, "callback_data", None) or "").lower()
            if "back" in d or any(w in t for w in _EIP_NAV_WORDS):
                return True
    return False


def _eip_with_back(markup):
    rows = [list(r) for r in markup.inline_keyboard] if markup is not None else []
    if markup is not None and _eip_has_nav(markup):
        return markup
    rows.append([InlineKeyboardButton(text=EIP_BACK_TEXT, callback_data=EIP_BACK_DATA)])
    return InlineKeyboardMarkup(inline_keyboard=rows)


def _eip_push(msg, text, markup):
    key = _eip_key(msg)
    st = _EIP_STACKS.pop(key, None) or []
    if not (st and st[-1]["text"] == text and st[-1]["markup"] == markup):
        st.append({"text": text, "markup": markup})
    if len(st) > _EIP_MAX_DEPTH:
        del st[0]
    _EIP_STACKS[key] = st
    while len(_EIP_STACKS) > _EIP_MAX_KEYS:
        _EIP_STACKS.popitem(last=False)


_eip_orig_answer = Message.answer


async def _eip_answer(self, text, *args, **kwargs):
    """callback.message.answer(...) -> iloji bo'lsa o'sha xabarni tahrirlaydi, bo'lmasa oddiy yangi xabar."""
    ctx = _EIP_CTX.get()
    try:
        if (ctx is not None and not ctx["done"] and not args and isinstance(text, str)
                and ctx["chat_id"] == self.chat.id and ctx["mid"] == self.message_id
                and set(kwargs) <= (_EIP_EDIT_KW | _EIP_IGNORE_KW)):
            markup = kwargs.get("reply_markup")
            if (markup is None or isinstance(markup, InlineKeyboardMarkup)) and self.text:
                snap_text = self.html_text
                snap_markup = self.reply_markup
                edit_kw = {k: v for k, v in kwargs.items() if k in _EIP_EDIT_KW}
                edit_kw["reply_markup"] = _eip_with_back(markup)
                ctx["done"] = True
                try:
                    res = await self.edit_text(text, **edit_kw)
                except TelegramBadRequest as e:
                    if "not modified" in str(e).lower():
                        return self
                    ctx["done"] = False      # tahrirlab bo'lmadi -> pastda oddiy yangi xabar
                else:
                    _eip_push(self, snap_text, snap_markup)
                    return res
    except (TelegramForbiddenError,):
        raise
    except Exception as e:
        logging.warning(f"edit-in-place xatosi, oddiy xabarga qaytildi: {e}")
    return await _eip_orig_answer(self, text, *args, **kwargs)


Message.answer = _eip_answer


class EditInPlaceMiddleware(BaseMiddleware):
    async def __call__(self, handler, event, data):
        msg = getattr(event, "message", None)
        if not isinstance(event, CallbackQuery) or not isinstance(msg, Message):
            return await handler(event, data)

        if event.data == EIP_BACK_DATA:
            st_ctx = data.get("state")
            if st_ctx is not None:
                try:
                    await st_ctx.clear()
                except Exception:
                    pass
            stack = _EIP_STACKS.get(_eip_key(msg))
            if not stack:
                await event.answer("Menyu eskirgan. /start ni bosing.", show_alert=True)
                return
            snap = stack.pop()
            try:
                await msg.edit_text(snap["text"], reply_markup=snap["markup"])
            except TelegramBadRequest as e:
                if "not modified" not in str(e).lower():
                    logging.warning(f"Orqaga qaytishda xato: {e}")
            await event.answer()
            return

        ctx = {"chat_id": msg.chat.id, "mid": msg.message_id, "done": False}
        token = _EIP_CTX.set(ctx)
        try:
            return await handler(event, data)
        finally:
            ctx["done"] = True
            _EIP_CTX.reset(token)


def install_edit_in_place(dp):
    dp.callback_query.outer_middleware(EditInPlaceMiddleware())


install_edit_in_place(main_dp)
