def _make_style_middleware(manual: bool):
    """Faqat tugma ranglarini qo'llaydigan yengil middleware.
    manual=True  — admin bergan ranglar + avtomatik qoidalar (Bot Creator klonlari uchun)
    manual=False — faqat avtomatik qoidalar (boshqa tur botlar uchun)
    Telegram rad etsa, asl (rangsiz) ko'rinishda yuboradi."""
    async def _mw(make_request, bot, method):
        styled = None
        try:
            mk = getattr(method, "reply_markup", None)
            new_mk = None
            if manual and isinstance(mk, InlineKeyboardMarkup):
                new_mk = btn_record_and_style(mk)
            elif manual and isinstance(mk, ReplyKeyboardMarkup):
                new_mk = btn_record_and_style_reply(mk)
            elif isinstance(mk, (InlineKeyboardMarkup, ReplyKeyboardMarkup)):
                new_mk = auto_style_markup(mk)
            if new_mk is not None:
                styled = method.model_copy(update={"reply_markup": new_mk})
        except Exception as e:
            logging.info(f"Tugma ranglari xatosi (e'tiborsiz): {e}")
        if styled is not None:
            try:
                return await make_request(bot, styled)
            except TelegramBadRequest as e:
                if "not modified" in str(e).lower():
                    raise
                logging.warning(f"Rangli tugmalar qabul qilinmadi, oddiy ko'rinishda yuborilmoqda: {e}")
        return await make_request(bot, method)
    return _mw


creator_style_request_middleware = _make_style_middleware(True)
auto_style_request_middleware = _make_style_middleware(False)

