_TEXT_VAR_RE = re.compile(r"\{(\w+)\}")
_TG_TAG_RE = re.compile(r"<(/?)([A-Za-z][A-Za-z0-9\-]*)(?:\s[^<>]*)?>")
_TG_ALLOWED_TAGS = {"b", "strong", "i", "em", "u", "ins", "s", "strike", "del", "code", "pre", "a",
                    "blockquote", "tg-spoiler", "tg-emoji", "span"}


def _html_problem(text: str):
    """Telegram HTML uchun oddiy tekshiruv: teglar ruxsat etilganmi va to'g'ri yopilganmi. Muammo bo'lsa matn qaytaradi."""
    stack = []
    for m in _TG_TAG_RE.finditer(text):
        closing, name = m.group(1) == "/", m.group(2).lower()
        if name not in _TG_ALLOWED_TAGS:
            return f"Ruxsat etilmagan HTML teg: <{name}>"
        if closing:
            if not stack or stack[-1] != name:
                return f"</{name}> tegi noto'g'ri joyda yoki ochilmagan."
            stack.pop()
        else:
            stack.append(name)
    if stack:
        return f"<{stack[-1]}> tegi yopilmagan."
    rest = _TG_TAG_RE.sub("", text)
    if "<" in rest or ">" in rest:
        return "Matnda ortiqcha '<' yoki '>' belgisi bor. Oddiy belgi sifatida &lt; va &gt; yozing."
    return None


def text_is_edited(key: str) -> bool:
    v = (data.get("custom_texts") or {}).get(key)
    return isinstance(v, str) and bool(v.strip())


def text_template(key: str) -> str:
    if text_is_edited(key):
        return data["custom_texts"][key]
    return TEXT_REGISTRY[key]["text"]


def _render_text(tpl: str, kw: dict) -> str:
    return _TEXT_VAR_RE.sub(lambda m: str(kw[m.group(1)]) if m.group(1) in kw else m.group(0), tpl)


def T(key: str, **kw) -> str:
    """Bot Creator matnini qaytaradi: admin tahrirlagan bo'lsa o'sha, bo'lmasa koddagi standart matn."""
    default = TEXT_REGISTRY[key]["text"]
    if text_is_edited(key):
        try:
            out = _render_text(data["custom_texts"][key], kw)
            if _html_problem(out) is None:
                return out
            logging.warning(f"Tahrirlangan matn ({key}) HTML xatosi tufayli standart matn ishlatildi")
        except Exception as e:
            logging.warning(f"Tahrirlangan matn ({key}) ishlamadi: {e}")
    return _render_text(default, kw)


def text_validate(key: str, text: str):
    """(ok, xato) qaytaradi."""
    if key not in TEXT_REGISTRY:
        return False, "Noma'lum matn."
    if not text or not text.strip():
        return False, "Matn bo'sh bo'lishi mumkin emas."
    if len(text) > 3500:
        return False, "Matn juda uzun (3500 belgidan oshmasin)."
    allowed = set(TEXT_REGISTRY[key]["vars"])
    bad = sorted({v for v in _TEXT_VAR_RE.findall(text) if v not in allowed})
    if bad:
        names = ", ".join("{" + b + "}" for b in bad)
        have = ", ".join("{" + a + "}" for a in allowed) or "yo'q"
        return False, f"Noma'lum o'zgaruvchi: {names}. Mavjud o'zgaruvchilar: {have}"
    prob = _html_problem(text)
    if prob:
        return False, prob
    return True, ""


def text_save(key: str, text: str):
    data.setdefault("custom_texts", {})[key] = text
    if TEXT_REGISTRY.get(key, {}).get("auto"):
        data.setdefault("auto_orig", {})[key] = TEXT_REGISTRY[key]["parts"]
    save_data()


def text_reset(key: str):
    data.setdefault("custom_texts", {}).pop(key, None)
    (data.get("auto_orig") or {}).pop(key, None)
    save_data()


# ===== 📝 AVTO-MATNLAR: koddagi har bir xabar matni avtomatik ro'yxatga olinadi =====
# Bot Creator'ning barcha xabar matnlari (kodda yozilgan f-string/oddiy matnlar) kod tahlili orqali topiladi
# va 📝 Matnlar menyusida tahrirlanadi. Tahrir BAZADA (data["custom_texts"]) + asl shabloni bilan
# (data["auto_orig"]) saqlanadi, shuning uchun kod yangilanganda ham eski matnga qaytmaydi.
data.setdefault("auto_orig", {})
_AUTO: dict = {}
_AT_SENDERS = {"answer", "edit_text", "send_message", "answer_photo", "edit_caption", "reply", "send_photo",
               "send_document", "answer_document", "send_video", "answer_video", "edit_message_text"}


def _at_flat(node):
    if isinstance(node, ast.Constant) and isinstance(node.value, str):
        return [["s", node.value]]
    if isinstance(node, ast.JoinedStr):
        out = []
        for v in node.values:
            if isinstance(v, ast.Constant):
                out.append(["s", str(v.value)])
            elif isinstance(v, ast.FormattedValue):
                out.append(["v", ast.unparse(v.value)])
        return out
    if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
        a, b = _at_flat(node.left), _at_flat(node.right)
        return a + b if a is not None and b is not None else None
    return None


def _at_key(parts) -> str:
    return "a_" + hashlib.md5(json.dumps(parts, ensure_ascii=False).encode("utf-8")).hexdigest()[:8]


def _at_entry(parts, legacy=False) -> dict:
    names, tpl, rx = {}, [], []
    for t, x in parts:
        if t == "s":
            tpl.append(x)
            rx.append(re.escape(x))
        else:
            if x not in names:
                names[x] = f"v{len(names) + 1}"
                rx.append(f"(?P<{names[x]}>.*?)")
            else:
                rx.append(f"(?P={names[x]})")
            tpl.append("{" + names[x] + "}")
    plain = re.sub(r"<[^>]+>", "", "".join(x if t == "s" else "…" for t, x in parts))
    first = next((ln.strip() for ln in plain.splitlines() if ln.strip()), "matn")
    return {
        "title": ("📦 (eski) " if legacy else "") + first[:44],
        "vars": {n: "avtomatik qiymat: " + e[:40] for e, n in names.items()},
        "sample": {n: "‹qiymat›" for n in names.values()},
        "text": "".join(tpl), "auto": True, "parts": parts,
        "rx": re.compile(r"\A" + "".join(rx) + r"\Z", re.S),
    }


def autotext_build():
    found = {}
    try:
        tree = ast.parse(open(__file__, encoding="utf-8").read())
        for fn in tree.body:
            if not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):
                continue
            uses_main = fn.name in ("setup_platform_bot", "trial_warning_loop", "topup_nudge_loop") or any(
                isinstance(n, ast.Name) and n.id == "main_bot" for n in ast.walk(fn))
            if not uses_main:
                continue
            for node in ast.walk(fn):
                if not (isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr in _AT_SENDERS):
                    continue
                for c in list(node.args[:2]) + [k.value for k in node.keywords if k.arg in ("text", "caption")]:
                    parts = _at_flat(c)
                    if not parts:
                        continue
                    static = "".join(x for t, x in parts if t == "s")
                    if len(static.strip()) < 8 or not re.search(r"[A-Za-zА-Яа-яʻ’']{3}", static):
                        continue
                    if sum(1 for t, _ in parts if t == "v") > 8:
                        continue
                    found.setdefault(_at_key(parts), parts)
    except Exception as e:
        logging.warning(f"Avto-matnlarni topishda xato: {e}")
    n_new = 0
    for key, parts in found.items():
        if key not in TEXT_REGISTRY:
            TEXT_REGISTRY[key] = _at_entry(parts)
            n_new += 1
    for key, parts in (data.get("auto_orig") or {}).items():  # kod o'zgargan, lekin tahrir saqlanib qolgan
        if key not in TEXT_REGISTRY and isinstance(parts, list):
            try:
                TEXT_REGISTRY[key] = _at_entry(parts, legacy=True)
            except Exception:
                pass
    _AUTO.clear()
    _AUTO.update({k: v for k, v in TEXT_REGISTRY.items() if v.get("auto")})
    logging.info(f"Avto-matnlar: {n_new} ta yangi, jami tahrirlanadigan matnlar: {len(TEXT_REGISTRY)}")


def autotext_apply(method):
    ct = data.get("custom_texts") or {}
    keys = [k for k in ct if k in _AUTO and text_is_edited(k)]
    if not keys:
        return method
    upd = {}
    is_cb = type(method).__name__ == "AnswerCallbackQuery"
    for field in ("text", "caption"):
        val = getattr(method, field, None)
        if not isinstance(val, str) or not val:
            continue
        for k in keys:
            m = _AUTO[k]["rx"].match(val)
            if not m:
                continue
            try:
                new = _render_text(ct[k], {n: m.group(n) for n in m.re.groupindex})
            except Exception:
                continue
            if is_cb:
                new = re.sub(r"<[^>]+>", "", new)[:200]
            elif _html_problem(new) is not None:
                continue
            upd[field] = new
            break
    return method.model_copy(update=upd) if upd else method


