    # Admin: /promo KOD SUMMA [LIMIT]  va  /promos
    @dp.message(Command("promo"))
    async def promo_create_cmd(message: Message):
        if not is_full_admin(message.from_user.id):
            return
        parts = (message.text or "").split()
        try:
            code = promo_normalize(parts[1])
            amount = int(parts[2])
            max_uses = int(parts[3]) if len(parts) > 3 else 0
            if not code or amount <= 0 or max_uses < 0:
                raise ValueError
        except (IndexError, ValueError):
            await message.answer(
                "Foydalanish: <code>/promo KOD SUMMA [LIMIT]</code>\n"
                "Masalan: <code>/promo YANGI50 5000 100</code> (LIMIT bo'lmasa — cheksiz)\n"
                "Ro'yxat: /promos"
            )
            return
        data["promo_codes"][code] = {
            "amount": amount, "max_uses": max_uses, "used_by": [],
            "active": True, "created_at": datetime.now().isoformat(timespec="seconds"),
        }
        save_data()
        await message.answer(f"✅ Promo-kod yaratildi: <code>{code}</code> — {amount:,} so'm, limit: {max_uses or 'cheksiz'}")

    @dp.message(Command("promos"))
    async def promo_list_cmd(message: Message):
        if not is_full_admin(message.from_user.id):
            return
        if not data["promo_codes"]:
            await message.answer("Hozircha promo-kodlar yo'q. Yaratish: /promo KOD SUMMA [LIMIT]")
            return
        lines = [
            f"{'🟢' if p.get('active', True) else '🔴'} <code>{c}</code> — {p['amount']:,} so'm | "
            f"{len(p.get('used_by', []))}/{p.get('max_uses') or '∞'}"
            for c, p in data["promo_codes"].items()
        ]
        await message.answer("🎟 <b>Promo-kodlar:</b>\n\n" + "\n".join(lines))

    @dp.message(F.text == "💰 Hisob to'ldirish")
    async def topup_start(message: Message, state: FSMContext):
        await message.answer(T("topup_prompt", min=f"{MIN_TOPUP:,}", max=f"{MAX_TOPUP:,}"))
        await state.set_state(TopUpFlow.waiting_amount)

    @dp.message(TopUpFlow.waiting_amount)
    async def topup_amount_process(message: Message, state: FSMContext):
        try:
            amount = int(message.text.strip().replace(" ", ""))
        except ValueError:
            await message.answer("❌ Faqat raqam kiriting.")
            return
        if amount < MIN_TOPUP or amount > MAX_TOPUP:
            await message.answer(f"❌ Summa {MIN_TOPUP:,} so'mdan {MAX_TOPUP:,} so'mgacha bo'lishi kerak.")
            return
        await state.update_data(topup_amount=amount)
        stars = somz_to_stars(amount)
        buttons = [[InlineKeyboardButton(text=f"⭐ {stars} Stars orqali to'lash", callback_data=f"topupstars_{amount}")]]
        buttons += [[InlineKeyboardButton(text=p["name"], callback_data=f"topuppay_{pid}")] for pid, p in data["payment_systems"].items()]
        await message.answer(
            f"💰 Summa: {amount:,} so'm (~{stars} ⭐)\n\n💳 To'lov tizimini tanlang:",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=buttons),
        )

    # ---------- 💬 Murojaat: foydalanuvchi xabari va admin javobi ----------
    @dp.message(SupportFlow.waiting_issue)
    async def support_issue_received(message: Message, state: FSMContext):
        body = (message.text or message.caption or "").strip()
        has_media = bool(message.photo or message.document or message.video or message.voice or message.audio or message.video_note)
        if not body and not has_media:
            await message.answer("✍️ Iltimos, muammoingizni matn yoki skrinshot ko'rinishida yuboring.")
            return
        await state.clear()
        u = message.from_user
        uname = f"@{u.username}" if u.username else "—"
        header = (
            "📩 <b>Yangi murojaat</b>\n"
            f"👤 {html_escape(u.full_name or '')} | {html_escape(uname)} | ID: <code>{u.id}</code>"
            + (f"\n\n{html_escape(body[:3500])}" if message.text else "")
        )
        reply_kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="↩️ Javob berish", callback_data=f"sup_reply_{u.id}")]])
        admins = {ADMIN_ID}
        for a in data.get("full_admins", []):
            try:
                admins.add(int(a))
            except (TypeError, ValueError):
                pass
        delivered = 0
        for a in admins:
            try:
                await message.bot.send_message(a, header, reply_markup=reply_kb)
                if not message.text:
                    await message.copy_to(chat_id=a)
                delivered += 1
            except Exception as e:
                logging.info(f"Murojaat adminga yetmadi ({a}): {e}")
        if delivered:
            await message.answer("✅ Murojaatingiz yuborildi. Tez orada javob beramiz.")
        else:
            await message.answer("⚠️ Murojaatni yuborib bo'lmadi. Iltimos, operatorga to'g'ridan-to'g'ri yozing 👇",
                                 reply_markup=InlineKeyboardMarkup(inline_keyboard=[[support_operator_btn()]]))

    @dp.message(SupportReply.waiting_text)
    async def support_reply_send(message: Message, state: FSMContext):
        if not is_full_admin(message.from_user.id):
            await state.clear()
            return
        st = await state.get_data()
        target = st.get("sup_target")
        body = (message.text or message.caption or "").strip()
        if not target or (not body and not (message.photo or message.document or message.video)):
            await message.answer("✍️ Javob matnini yozing (bekor qilish: /cancel).")
            return
        await state.clear()
        try:
            await message.bot.send_message(target, "💬 <b>Qo'llab-quvvatlash javobi:</b>\n\n" + html_escape(body[:3800]) if message.text else "💬 <b>Qo'llab-quvvatlash javobi:</b>")
            if not message.text:
                await message.copy_to(chat_id=target)
            await message.answer("✅ Javob yuborildi.")
        except Exception as e:
            await message.answer(f"❌ Javob yuborilmadi: {html_escape(str(e)[:200])}")

