    @dp.callback_query(F.data.regexp(r"^mbs_[a-z]+_\d+$"))
    async def mbs_router(callback: CallbackQuery, state: FSMContext):
        _, act, sid = callback.data.split("_", 2)
        bot_id = int(sid)
        owner_acts = {"tok", "cp", "adm", "give", "giveok", "del", "delok"}
        token, info = mb_access(callback.from_user.id, bot_id, owner_only=(act in owner_acts))
        if not info:
            await callback.answer("Ruxsat yo'q." if act not in owner_acts else "Bu amal faqat bot egasi uchun.", show_alert=True)
            return
        await state.clear()
        bid = info["id"]

        if act == "menu":
            text, kb = await mb_settings_view(token, info)
            await mb_edit(callback, text, kb)
        elif act == "prof":
            text, kb = await mb_profile_view(token, info)
            await mb_edit(callback, text, kb)
        elif act == "tok":
            uname = await mb_username(token, info)
            await state.set_state(BotMgrFlow.waiting_token)
            await state.update_data(mbs_id=bid)
            await mb_edit(callback,
                "🔑 <b>Tokenni almashtirish</b>\n\nBotning yangi tokenini shu yerga yuboring.\n\n"
                "<blockquote expandable>📌 <b>Token qayerdan olinadi?</b>\n1. @BotFather ni oching\n2. /mybots → botingizni tanlang\n"
                "3. «API Token» tugmasini bosing\n4. Chiqqan kodni nusxalab shu yerga tashlang</blockquote>\n\n"
                f"⚠️ <i>Token aynan shu botniki bo'lishi kerak{(' (@' + html_escape(uname) + ')') if uname else ''}.</i>",
                mb_back_kb(bid))
        elif act == "cp":
            await mb_edit(callback,
                f"🔑 <b>Bot tokeni:</b>\n\n<code>{html_escape(token)}</code>\n\n<i>Nusxalab olish uchun token ustiga bosing.</i>\n"
                "⚠️ Tokenni hech kimga bermang.",
                mb_back_kb(bid))
        elif act == "fix":
            err = None
            try:
                await tg_api(token, "getMe")
            except Exception as e:
                err = str(e)
            if err:
                await mb_edit(callback,
                    f"❌ <b>Bot tokeni ishlamayapti</b>\n\n<code>{html_escape(err[:200])}</code>\n\n"
                    "Token BotFather'da bekor qilingan yoki o'zgartirilgan bo'lishi mumkin. Yangi token oling va uni almashtiring.",
                    InlineKeyboardMarkup(inline_keyboard=[
                        [InlineKeyboardButton(text="🔑 Tokenni almashtirish", callback_data=f"mbs_tok_{bid}")],
                        [InlineKeyboardButton(text="◀️ Orqaga", callback_data=f"mbs_menu_{bid}")],
                    ]))
            else:
                task = running_bots.pop(token, None)
                if task:
                    task.cancel()
                await asyncio.sleep(0.7)
                await start_child_bot(token, info["type"])
                uname = await mb_username(token, info)
                note = "" if is_active(info) else "\n\n⚠️ Bot to'xtatilgan: muddati tugagan. Ishlashi uchun «💰 To'lov» orqali obunani uzaytiring."
                await mb_edit(callback,
                    f"✅ <b>Bot qayta ishga tushirildi!</b>\n\n{('@' + html_escape(uname)) if uname else html_escape(info['name'])} endi ishlashi kerak.\n\n"
                    "<blockquote>💡 Botingizga /start yozib tekshiring. Agar hali ham javob bermasa, tokenni almashtirib ko'ring yoki administrator bilan bog'laning.</blockquote>"
                    + note,
                    InlineKeyboardMarkup(inline_keyboard=[
                        [InlineKeyboardButton(text="💬 Admin bilan bog'lanish", url=admin_contact_url())],
                        [InlineKeyboardButton(text="◀️ Orqaga", callback_data=f"mbs_menu_{bid}")],
                    ]))
        elif act == "adm":
            await state.set_state(BotMgrFlow.waiting_admin)
            await state.update_data(mbs_id=bid)
            await mb_edit(callback,
                "🆔 <b>Adminni o'zgartirish</b>\n\nYangi adminning Telegram ID raqamini yuboring (masalan: <code>7458702074</code>).\n\n"
                "ℹ️ Botning boshqa adminlari o'rniga shu foydalanuvchi admin bo'ladi. Siz (bot egasi) botni shu yerdan boshqarish huquqini saqlab qolasiz.",
                mb_back_kb(bid))
        elif act == "give":
            await state.set_state(BotMgrFlow.waiting_give)
            await state.update_data(mbs_id=bid)
            await mb_edit(callback,
                "📦 <b>Botni boshqa odamga berish</b>\n\nBotni qabul qilib oluvchi foydalanuvchining Telegram ID raqamini yuboring.\n\n"
                "ℹ️ U avval shu platforma botiga kirib /start bosgan bo'lishi kerak.",
                mb_back_kb(bid))
        elif act == "giveok":
            st = await state.get_data()
            new_id = st.get("mbs_give_to")
            await mb_edit(callback, "⚠️ Amal eskirgan. Qaytadan urinib ko'ring.", mb_back_kb(bid))
        elif act == "del":
            await mb_edit(callback,
                f"🗑 <b>{html_escape(info['name'])}</b> botini o'chirmoqchimisiz?\n\n"
                "Bot to'xtatiladi va barcha ma'lumotlari (kinolar, foydalanuvchilar, sozlamalar) dasturdan butunlay o'chiriladi. "
                "<b>Bu amalni qaytarib bo'lmaydi.</b>",
                InlineKeyboardMarkup(inline_keyboard=[
                    [InlineKeyboardButton(text="🗑 Ha, o'chirish", callback_data=f"mbs_delok_{bid}", style="danger")],
                    [InlineKeyboardButton(text="❌ Bekor qilish", callback_data=f"mb_{bid}")],
                ]))
        elif act == "delok":
            task = running_bots.pop(token, None)
            if task:
                task.cancel()
            data["bots"].pop(token, None)
            save_data()
            text, kb = mybots_list_view(callback.from_user.id)
            await mb_edit(callback, f"🗑 <b>{html_escape(info['name'])}</b> o'chirildi.\n\n" + text, kb)
        elif act in ("name", "bio", "desc", "photo", "cmds"):
            prompts = {
                "name": ("✏️ <b>Bot nomi</b>\n\nYangi nomni yuboring (maks 64 belgi).", BotMgrFlow.waiting_name),
                "bio": ("💬 <b>Bio (qisqa matn)</b>\n\nBot profilida chiqadigan qisqa matnni yuboring (maks 120 belgi).", BotMgrFlow.waiting_bio),
                "desc": ("📝 <b>Tavsif</b>\n\nBot birinchi marta ochilganda chiqadigan tavsifni yuboring (maks 512 belgi).", BotMgrFlow.waiting_desc),
                "photo": ("🖼 <b>Profil rasmi</b>\n\nYangi rasmni oddiy rasm (surat) ko'rinishida yuboring.", BotMgrFlow.waiting_photo),
            }
            if act == "cmds":
                try:
                    cur = await tg_api(token, "getMyCommands")
                except Exception:
                    cur = []
                cur_txt = "\n".join(f"/{c['command']} — {html_escape(c['description'])}" for c in (cur or [])) or "—"
                text = (
                    "📋 <b>Buyruqlar</b>\n\nHozirgi ro'yxat:\n" f"<blockquote expandable>{cur_txt}</blockquote>\n\n"
                    "Yangi ro'yxatni har qatorga bittadan yuboring:\n<code>start - Botni ishga tushirish\nhelp - Yordam</code>\n\n"
                    "Hammasini o'chirish uchun <code>0</code> yuboring."
                )
                await state.set_state(BotMgrFlow.waiting_cmds)
            else:
                text, st_obj = prompts[act]
                await state.set_state(st_obj)
            await state.update_data(mbs_id=bid)
            await mb_edit(callback, text, mb_back_kb(bid, "prof"))
        elif act in ("biox", "descx", "photox"):
            try:
                if act == "biox":
                    await tg_api(token, "setMyShortDescription", {"short_description": ""})
                elif act == "descx":
                    await tg_api(token, "setMyDescription", {"description": ""})
                else:
                    await tg_api(token, "removeMyProfilePhoto")
                toast = "🗑 O'chirildi"
            except Exception as e:
                toast = f"❌ {str(e)[:150]}"
            text, kb = await mb_profile_view(token, info)
            await mb_edit(callback, text, kb, toast)
            return
        else:
            await callback.answer()
            return
        # mb_edit allaqachon callback.answer() ni chaqirgan

    async def mgr_guard(message: Message, state: FSMContext):
        """Menyu tugmasi yoki buyruq bosilsa jarayonni bekor qiladi. True — to'xtatish kerak."""
        t = (message.text or "").strip()
        if t in MB_MENU_TEXTS or t.startswith("/"):
            await state.clear()
            await message.answer("❌ Jarayon bekor qilindi. Kerakli tugmani qayta bosing.")
            return True
        return False

    async def mgr_ctx(message: Message, state: FSMContext, owner_only: bool = False):
        st = await state.get_data()
        token, info = mb_access(message.from_user.id, st.get("mbs_id", 0), owner_only=owner_only)
        if not info:
            await state.clear()
            await message.answer("❌ Bot topilmadi yoki ruxsat yo'q.")
            return None, None
        return token, info

    @dp.message(BotMgrFlow.waiting_token)
    async def mgr_token_received(message: Message, state: FSMContext):
        if await mgr_guard(message, state):
            return
        token, info = await mgr_ctx(message, state, owner_only=True)
        if not info:
            return
        new = (message.text or "").strip()
        try:
            await message.delete()      # token chatda qolib ketmasin
        except Exception:
            pass
        if new == token:
            await message.answer("ℹ️ Bu — hozirgi token. Yangi token yuboring.", reply_markup=mb_back_kb(info["id"]))
            return
        if new.split(":")[0] != token.split(":")[0]:
            await message.answer("❌ Bu token boshqa botniki. Aynan shu botning yangi tokenini yuboring.", reply_markup=mb_back_kb(info["id"]))
            return
        if new in data["bots"]:
            await message.answer("❌ Bu token tizimda allaqachon mavjud.", reply_markup=mb_back_kb(info["id"]))
            return
        try:
            me = await tg_api(new, "getMe")
        except Exception:
            await message.answer("❌ Token noto'g'ri yoki ishlamayapti. Qaytadan yuboring.", reply_markup=mb_back_kb(info["id"]))
            return
        await state.clear()
        task = running_bots.pop(token, None)
        if task:
            task.cancel()
        data["bots"][new] = data["bots"].pop(token)
        info["username"] = me.get("username")
        save_data()
        await asyncio.sleep(0.7)
        await start_child_bot(new, info["type"])
        await message.answer("✅ <b>Token almashtirildi.</b> Bot yangi token bilan qayta ishga tushirildi.",
                             reply_markup=mb_back_kb(info["id"], "menu"))

