    # ---------- 📦 Tayyor paketlar: 1 / 3 / 12 oylik, uzoqrog'i arzonroq ----------
    def _round_k(n: float) -> int:
        return max(1000, int(round(n / 1000.0)) * 1000)

    @dp.callback_query(F.data == "pt_pack")
    async def pt_pack_cb(callback: CallbackQuery, state: FSMContext):
        if not is_admin(info, callback.from_user.id):
            return
        await state.set_state(PremiumPack.price)
        await callback.message.answer(
            "📦 <b>Tayyor Premium paketlar</b>\n\n"
            "Bot 3 ta tarif yaratadi: <b>1 oylik</b>, <b>3 oylik</b>, <b>12 oylik</b> — uzoq muddatli paket arzonroq bo'ladi.\n\n"
            "Oylik narxni yuboring (so'mda). Chegirmani ham yozishingiz mumkin:\n"
            "• <code>30000</code> — 3 oy −10%, 12 oy −25% (standart)\n"
            "• <code>30000 15 35</code> — 3 oy −15%, 12 oy −35%\n\n"
            "Bekor qilish: /cancel")
        await callback.answer()

    @dp.message(PremiumPack.price, F.text)
    async def pt_pack_price(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        parts = re.findall(r"\d+", (message.text or "").replace(" ", " "))
        if not parts or int(parts[0]) < 1000:
            await message.answer("❌ Oylik narxni raqamda yozing (kamida 1000 so'm), masalan: 30000")
            return
        month = int(parts[0])
        d3 = int(parts[1]) if len(parts) > 1 else 10
        d12 = int(parts[2]) if len(parts) > 2 else 25
        if not (0 <= d3 <= 70 and 0 <= d12 <= 80):
            await message.answer("❌ Chegirma 0 dan 70 gacha (12 oy uchun 80 gacha) bo'lishi kerak.")
            return
        for tid in [t for t, v in info["premium_tariffs"].items() if v.get("pack")]:
            info["premium_tariffs"].pop(tid, None)
        plan = [("1 oylik", 30, month, 0), ("3 oylik", 90, _round_k(month * 3 * (100 - d3) / 100), d3),
                ("12 oylik", 365, _round_k(month * 12 * (100 - d12) / 100), d12)]
        lines = []
        for name, days, price, disc in plan:
            info["premium_tariffs"][uuid.uuid4().hex[:8]] = {"name": name, "days": days, "price": price, "pack": True}
            lines.append(f"• {name} ({days} kun) — <b>{price:,} so'm</b>" + (f"  (−{disc}%)" if disc else ""))
        info["premium_enabled"] = True
        save_data()
        await state.clear()
        await message.answer("✅ <b>Premium paketlar tayyor:</b>\n\n" + "\n".join(lines) +
                             "\n\nObunachilar tariflar ro'yxatida «🔥 % tejash» belgisini ko'radi.")

