        lines = [f"#{oid[:6]} — ⭐{o['stars']:,} — {o['price']:,} so'm — ID:{o['user_id']}" for oid, o in orders[-20:]]
        return f"{emoji} <b>Buyurtmalar ({len(orders)}):</b>\n\n" + "\n".join(lines)

