    # ---------- 🌐 Til + faollik kuzatuvi (faqat Kino bot) ----------
    class _KinoLangMW(BaseMiddleware):
        """Obunachi pastki menyudagi tugmani ruscha/inglizcha bossa — uni o'zbekcha tugmaga qaytaradi;
        til o'zgargach, har bir obunachiga yangi tildagi menyuni bir marta qayta yuboradi."""
        async def __call__(self, handler, event, payload):
            try:
                u = getattr(event, "from_user", None)
                if u and not is_moderator(u.id) and not is_blocked(u.id):
                    lang = info.get("language", "uz")
                    txt = getattr(event, "text", None)
                    if txt:
                        uz_txt = KINO_I18N_REV.get(txt)
                        if uz_txt:
                            event = event.model_copy(update={"text": uz_txt})
                    kbl = info.setdefault("kb_lang", {})
                    if kbl.get(str(u.id), "uz") != lang:
                        kbl[str(u.id)] = lang
                        if not (txt or "").startswith("/start"):
                            await event.answer(
                                "📋 Bot menyusi yangilandi — pastdagi tugmalardan foydalaning 👇",
                                reply_markup=customer_menu_kb(),
                            )
            except Exception as e:
                logging.warning(f"Til middleware xatosi (e'tiborsiz): {e}")
            return await handler(event, payload)

    class _KinoTrackMW(BaseMiddleware):
        """Obunachining oxirgi faolligini yozib boradi (statistika: «Faollik»)."""
        async def __call__(self, handler, event, payload):
            try:
                m = getattr(event, "message", None) or getattr(event, "callback_query", None)
                u = getattr(m, "from_user", None)
                if u and not is_moderator(u.id):
                    info.setdefault("last_seen", {})[str(u.id)] = int(datetime.now().timestamp())
            except Exception:
                pass
            return await handler(event, payload)

    class _KindRevMW(BaseMiddleware):
        """Media bot turiga moslangan tugma matni bosilganda — uni asl (ichki) matnga qaytaradi."""
        async def __call__(self, handler, event, payload):
            try:
                if media_kind_of(info) != "kino":
                    txt = getattr(event, "text", None)
                    orig = (info.get("kind_rev") or {}).get(txt) if txt else None
                    if orig:
                        event = event.model_copy(update={"text": orig})
            except Exception as e:
                logging.warning(f"Media tur middleware (kiruvchi) xatosi: {e}")
            return await handler(event, payload)

    dp.message.outer_middleware(_KindRevMW())
    dp.message.outer_middleware(_KinoLangMW())
    dp.update.outer_middleware(_KinoTrackMW())

    class _KinoPermMW(BaseMiddleware):
        """🔐 Bot egasi bergan ruxsatlarni majburiy qiladi: admin o'ziga yopiq bo'limga kira olmaydi.
        Bot egasi va ruxsati cheklanmagan (eski) adminlarga ta'sir qilmaydi."""
        async def __call__(self, handler, event, payload):
            try:
                u = getattr(event, "from_user", None)
                if u and is_admin(info, u.id) and not is_bot_owner(info, u.id):
                    deny = None
                    txt = getattr(event, "text", None)
                    cdata = getattr(event, "data", None)
                    if txt:
                        if txt in ADMIN_OWNER_ONLY_TEXTS:
                            deny = "🚫 Bu bo'limni faqat bot egasi boshqara oladi."
                        else:
                            perm = ADMIN_TEXT_PERM.get(txt)
                            if perm and not admin_has_perm(info, u.id, perm):
                                deny = "🚫 Sizda bu bo'limga ruxsat yo'q.\nRuxsat berishni bot egasidan so'rang."
                    elif cdata:
                        for pref, perm in ADMIN_CB_PERM.items():
                            if cdata.startswith(pref) and not admin_has_perm(info, u.id, perm):
                                deny = "🚫 Sizda bu amalga ruxsat yo'q."
                                break
                    if deny:
                        if hasattr(event, "answer") and not cdata:
                            await event.answer(deny)
                        else:
                            await event.answer(deny, show_alert=True)
                        return None
            except Exception as e:
                logging.warning(f"Ruxsat middleware xatosi (e'tiborsiz): {e}")
            return await handler(event, payload)

    dp.message.outer_middleware(_KinoPermMW())
    dp.callback_query.outer_middleware(_KinoPermMW())

