    # ---------- 📮 Postlar: kanalni tanlab, tugmali post tayyorlash va yuborish ----------
    POST_COLORS = {
        "yashil": "success", "green": "success", "зеленый": "success", "зелёный": "success",
        "ko'k": "primary", "kok": "primary", "blue": "primary", "синий": "primary",
        "qizil": "danger", "red": "danger", "красный": "danger",
    }
    POST_MAX_BUTTONS = 30
    POST_SEP_RE = re.compile(r"\s*[—–]\s*|\s+-\s+")

    def post_targets() -> list:
        """Bot admin bo'lgan kanallar: majburiy obuna kanallari + auto-post kanallari (takrorlarsiz)."""
        out, seen = [], set()

        def add(cid, title):
            cid = str(cid)
            if cid in seen or not cid.lstrip("-").isdigit():
                return
            seen.add(cid)
            out.append({"id": cid, "title": str(title or cid)})

        for key, c in (info.get("channels") or {}).items():
            if isinstance(c, dict) and c.get("type") == "telegram":
                add(key, c.get("title") or c.get("username"))
        for c in info.get("autopost_channels", []) or []:
            add(c.get("chat_id"), c.get("title") or (("@" + c["username"]) if c.get("username") else None))
        return out

    def postbuild_kb():
        return ReplyKeyboardMarkup(keyboard=[
            [KeyboardButton(text="➕ Tugma qo'shish"), KeyboardButton(text="📝 Text qo'shish")],
            [KeyboardButton(text="✅ Tamomlash"), KeyboardButton(text="⏰ Rejalashtirish")],
            [KeyboardButton(text="◀️ Orqaga")],
        ], resize_keyboard=True)

    def post_parse_one(part: str):
        """«Matn — havola — rang» -> {"t","u","s"} yoki None. Ajratgich: — , – yoki bo'sh joyli ' - '."""
        pieces = [x.strip() for x in POST_SEP_RE.split(part.strip()) if x.strip()]
        style = None
        if len(pieces) >= 3:
            w = re.sub(r"[\U0001F7E2\U0001F535\U0001F534\U0001F7E9\U0001F7E6\U0001F7E5]", "",
                       pieces[-1].translate(_AUTO_APOS).lower()).strip(" .!")
            if w in POST_COLORS:
                style = POST_COLORS[w]
                pieces = pieces[:-1]
        if len(pieces) < 2:
            return None
        url_ = kino_norm_btn_url(pieces[-1])
        text_ = " - ".join(pieces[:-1]).strip()[:60]
        if not url_ or not text_:
            return None
        return {"t": text_, "u": url_, "s": style}

    def post_parse_buttons(raw: str):
        """(qatorlar, xato_qator_raqami, xato_matni). Har qator = yangi qator, '|' = bir qatorda bir nechta."""
        rows, total = [], 0
        for n, line in enumerate((raw or "").splitlines(), 1):
            line = line.strip()
            if not line:
                continue
            row = []
            for part in line.split("|"):
                if not part.strip():
                    continue
                b = post_parse_one(part)
                if b is None:
                    return None, n, part.strip()
                row.append(b)
                total += 1
            if row:
                rows.append(row[:8])
        if total > POST_MAX_BUTTONS:
            return None, -1, ""
        return rows, 0, ""

    def post_markup(d: dict, plain: bool = False):
        rows = d.get("rows") or []
        if not rows:
            return None
        kb = []
        for r in rows:
            line = []
            for b in r:
                kw = {}
                if b.get("s") and not plain:
                    kw["style"] = b["s"]
                line.append(InlineKeyboardButton(text=b["t"], url=b["u"], **kw))
            kb.append(line)
        return InlineKeyboardMarkup(inline_keyboard=kb)

    POST_BOT_TARGET = "bot"
    POST_BOT_TITLE = "🤖 Bot obunachilari"

    async def _post_send_one(b, chat_id, d: dict, plain: bool):
        text = d.get("text") or ""
        kind = d.get("kind")
        mk = post_markup(d, plain=plain)
        if kind == "photo":
            return await b.send_photo(chat_id, d["file_id"], caption=text or None, reply_markup=mk)
        if kind == "video":
            return await b.send_video(chat_id, d["file_id"], caption=text or None, reply_markup=mk)
        if kind == "animation":
            return await b.send_animation(chat_id, d["file_id"], caption=text or None, reply_markup=mk)
        return await b.send_message(chat_id, text, reply_markup=mk)

    def post_recipients() -> list:
        """Botga post yuborish: bloklanmagan obunachilar (adminlar ham kiradi)."""
        blocked = set(info.get("blocked_users", []) or [])
        out = []
        for u in (info.get("users") or []):
            try:
                u = int(u)
            except Exception:
                continue
            if u not in blocked:
                out.append(u)
        return list(dict.fromkeys(out))

    async def post_deliver(chat_id, d: dict):
        """Postni yuboradi (kanalga, botning obunachilariga yoki ko'rinish uchun adminga). Alohida Bot orqali —
        tugma ranglari faqat siz tanlaganicha qoladi. Rang qabul qilinmasa — rangsiz qayta urinadi.
        chat_id == "bot" bo'lsa — botning barcha obunachilariga yuboriladi va (yuborildi, xato) qaytaradi."""
        has_color = any(x.get("s") for r in (d.get("rows") or []) for x in r)
        b = _new_bot(token)
        try:
            if str(chat_id) == POST_BOT_TARGET:
                sent = failed = 0
                plain = False
                for uid_ in post_recipients():
                    for attempt in range(2):
                        try:
                            await _post_send_one(b, uid_, d, plain)
                            sent += 1
                            break
                        except TelegramBadRequest as ex:
                            if not plain and has_color:
                                plain = True        # rang qabul qilinmadi — qolganlariga rangsiz
                                continue
                            failed += 1
                            break
                        except Exception as ex:
                            ra = getattr(ex, "retry_after", None)
                            if ra and attempt == 0:
                                await asyncio.sleep(min(int(ra) + 1, 30))
                                continue
                            failed += 1
                            break
                    await asyncio.sleep(0.05)
                return sent, failed
            for plain in (False, True):
                try:
                    return await _post_send_one(b, chat_id, d, plain)
                except TelegramBadRequest as ex:
                    if plain or not has_color:
                        raise
                    logging.warning(f"Rangli post tugmalari qabul qilinmadi, rangsiz yuborilmoqda: {ex}")
        finally:
            await _close_bot(b)

    async def post_show(message: Message, state: FSMContext, note: str = ""):
        """Post ko'rinishini va menyuni ko'rsatadi."""
        d = await state.get_data()
        has_content = bool(d.get("pst_text") or d.get("pst_file"))
        rows = d.get("pst_rows") or []
        if has_content:
            try:
                await post_deliver(message.chat.id, {"kind": d.get("pst_kind"), "file_id": d.get("pst_file"),
                                                     "text": d.get("pst_text"), "rows": rows})
            except Exception as ex:
                await message.answer(f"⚠️ Ko'rinishni ko'rsatib bo'lmadi: {html_escape(str(ex)[:150])}")
        n = sum(len(r) for r in rows)
        has_media = bool(d.get("pst_file"))
        has_text = bool(d.get("pst_text"))
        status = [f"📮 <b>Post</b> → «{html_escape(d.get('pst_title') or '')}»",
                  f"🎬 Video: {'✅' if has_media else '—'}   📝 Matn: {'✅' if has_text else '—'}   🔘 Tugmalar: {n} ta"]
        if note:
            status.insert(0, note)
        if not has_content:
            status.append("\nPost bo'sh. «📝 Text qo'shish» ni bosing yoki videoni yuboring.")
        elif has_media and not has_text:
            status.append("\n«📝 Text qo'shish» orqali video izohini yozing, «➕ Tugma qo'shish» orqali tugmalar qo'shing.")
        else:
            status.append("\nTayyor bo'lsa — «✅ Tamomlash» (kanalga yuboriladi).")
        await message.answer("\n".join(status), reply_markup=postbuild_kb())

