    @dp.callback_query(F.data.startswith("pst_c_"))
    async def post_pick_channel(callback: CallbackQuery, state: FSMContext):
        if not is_admin(info, callback.from_user.id):
            await callback.answer()
            return
        cid = callback.data.split("_", 2)[2]
        if cid == POST_BOT_TARGET:
            ch = {"id": cid, "title": POST_BOT_TITLE}
        else:
            ch = next((c for c in post_targets() if c["id"] == cid), None)
        if not ch:
            await callback.answer("Kanal topilmadi.", show_alert=True)
            return
        await state.clear()
        await state.set_state(PostBuild.text)      # avval media (video) so'raladi
        await state.update_data(pst_chat=cid, pst_title=ch["title"], pst_kind=None, pst_file=None, pst_text="", pst_rows=[])
        await callback.message.answer(
            f"📮 <b>Post</b> → «{html_escape(ch['title'])}»\n\n"
            "🎬 <b>Avval post videosini yuboring</b> (forward qilsangiz ham bo'ladi). Rasm yoki GIF ham mumkin.\n"
            "Videoning izohi post matni bo'ladi — keyin «📝 Text qo'shish» orqali o'zgartirasiz.\n\n"
            "Faqat matnli post kerak bo'lsa — matnni shu yerda yuboring.",
            reply_markup=postbuild_kb())
        await callback.answer()

    async def post_need_channel(message: Message, state: FSMContext) -> bool:
        d = await state.get_data()
        if not d.get("pst_chat"):
            await message.answer("Avval «📮 Postlar» bo'limidan kanalni tanlang.")
            return False
        return True

