    @dp.message(F.text == "✅ Tamomlash")
    async def post_finish(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id) or not await post_need_channel(message, state):
            return
        d = await state.get_data()
        if not (d.get("pst_text") or d.get("pst_file")):
            await message.answer("❌ Avval «📝 Text qo'shish» orqali post matnini kiriting.", reply_markup=postbuild_kb())
            return
        to_bot = str(d["pst_chat"]) == POST_BOT_TARGET
        pd = {"kind": d.get("pst_kind"), "file_id": d.get("pst_file"),
              "text": d.get("pst_text"), "rows": d.get("pst_rows") or []}
        if to_bot:
            await state.clear()
            await message.answer(f"🚀 Post {len(post_recipients())} ta obunachiga yuborilmoqda... Tugagach xabar beraman.",
                                 reply_markup=ultra_admin_kb())

            async def _bg(chat_id=message.chat.id):
                try:
                    sent, failed = await post_deliver(POST_BOT_TARGET, pd)
                    txt = f"✅ Post botga yuborildi!\n\n📨 Yetkazildi: <b>{sent}</b>\n🚫 Yetkazilmadi: {failed} (botni bloklaganlar)"
                except Exception as ex:
                    logging.error(f"Botga post yuborishda xato: {ex}")
                    txt = "❌ Botga post yuborishda xatolik yuz berdi."
                try:
                    await message.bot.send_message(chat_id, txt)
                except Exception:
                    pass
            asyncio.create_task(_bg())
            return
        try:
            await post_deliver(int(d["pst_chat"]), pd)
        except (TelegramForbiddenError, TelegramBadRequest) as ex:
            await message.answer(
                "❌ Postni kanalga yuborib bo'lmadi.\n"
                "Bot kanalda <b>admin</b> bo'lishi va «Xabar yuborish» huquqiga ega bo'lishi kerak.\n\n"
                f"<i>{html_escape(str(ex)[:150])}</i>", reply_markup=postbuild_kb())
            return
        except Exception as ex:
            logging.error(f"Post yuborishda xato: {ex}")
            await message.answer("❌ Xatolik yuz berdi. Birozdan so'ng qayta urinib ko'ring.", reply_markup=postbuild_kb())
            return
        await state.clear()
        await message.answer(f"✅ Post «{html_escape(d.get('pst_title') or '')}» kanaliga yuborildi!",
                             reply_markup=ultra_admin_kb())

    @dp.message(PostBuild.text, F.text | F.photo | F.video | F.animation)
    async def post_text_save(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        d = await state.get_data()
        kind, file_id = d.get("pst_kind"), d.get("pst_file")
        got_media = False
        if message.photo:
            kind, file_id, got_media = "photo", message.photo[-1].file_id, True
        elif message.video:
            kind, file_id, got_media = "video", message.video.file_id, True
        elif message.animation:
            kind, file_id, got_media = "animation", message.animation.file_id, True
        text = (message.html_text or "").strip()
        if not got_media:
            if not text or text.startswith("/"):
                await message.answer("❌ Video yuboring yoki post matnini oddiy matn ko'rinishida yozing.")
                return
        else:
            if not text:
                text = d.get("pst_text") or ""      # izohsiz video — oldingi matn saqlanadi
        if kind and len(text) > 1024:
            await message.answer("❌ Video/rasm izohi 1024 belgidan oshmasin. Qisqartirib qayta yuboring.")
            return
        if len(text) > 4000:
            await message.answer("❌ Matn juda uzun (4000 belgigacha).")
            return
        await state.update_data(pst_kind=kind, pst_file=file_id, pst_text=text)
        await state.set_state(PostBuild.menu)
        await post_show(message, state, "✅ Video saqlandi." if got_media else "✅ Matn saqlandi.")

    @dp.message(PostBuild.buttons, F.text)
    async def post_buttons_save(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        raw = message.text or ""
        if raw.strip().lower() in ("tozalash", "o'chirish", "ochirish", "clear"):
            await state.update_data(pst_rows=[])
            await state.set_state(PostBuild.menu)
            await post_show(message, state, "🧹 Tugmalar tozalandi.")
            return
        rows, bad_n, bad_txt = post_parse_buttons(raw)
        if rows is None:
            if bad_n == -1:
                await message.answer(f"❌ Tugmalar ko'p. Ko'pi bilan {POST_MAX_BUTTONS} ta bo'lishi mumkin.")
            else:
                await message.answer(
                    f"❌ {bad_n}-qatordagi «{html_escape(bad_txt[:60])}» tugmasini o'qib bo'lmadi.\n\n"
                    "Shakl: <code>Matn — havola — rang</code>\n"
                    "Masalan: <code>🎬KINONI KO'RISH - https://t.me/bot?start=8 - YASHIL</code>\n\n"
                    "Qayta yuboring:")
            return
        if not rows:
            await message.answer("❌ Tugma topilmadi. Namunaga qarab yuboring yoki «◀️ Orqaga» ni bosing.")
            return
        await state.update_data(pst_rows=rows)
        await state.set_state(PostBuild.menu)
        await post_show(message, state, f"✅ {sum(len(r) for r in rows)} ta tugma saqlandi.")

