    # ---------- ↗️ Ulashish (kinoni boshqa chatga yuborishni taqiqlash) ----------
    def kino_protect(uid, code=None) -> bool:
        """Videoni forward qilish va saqlashni taqiqlash kerakmi (adminlarga tegmaydi)."""
        if uid is not None and is_admin(info, uid):
            return False
        if info.get("protect_content"):
            return True
        if code and info.get("protect_premium"):
            e = info["movies"].get(code) or {}
            if e.get("access") == "paid" or code in info.get("vip_codes", []):
                return True
        return False

