    # ---------- Statistika ----------
    def kino_stats_text() -> str:
        now = datetime.now()
        nowts = now.timestamp()
        total = len(info["users"])
        left = len(info.get("left_users", {}))
        jl = info.get("join_log", {})
        jts = info.get("join_ts", {})

        def joined(days: int) -> int:
            since_date = (now - timedelta(days=days - 1)).strftime("%Y-%m-%d")
            n = 0
            for uid_s, d in jl.items():
                ts = jts.get(uid_s)
                if ts is not None:
                    n += 1 if ts >= nowts - days * 86400 else 0
                elif d >= since_date:      # eski yozuvlarda faqat sana bor
                    n += 1
            return n

        ls = info.get("last_seen", {})

        def active(days: int) -> int:
            return sum(1 for t in ls.values() if t >= nowts - days * 86400)

        dv = info.get("daily_views", {})
        vh = info.get("views_hourly", {})

        def views(days: int) -> int:
            if days == 1:
                if vh:
                    cutoff = (now - timedelta(hours=24)).strftime("%Y-%m-%d %H")
                    return sum(v for k, v in vh.items() if k > cutoff)
                return dv.get(now.strftime("%Y-%m-%d"), 0)
            since = (now - timedelta(days=days - 1)).strftime("%Y-%m-%d")
            return sum(v for k, v in dv.items() if k >= since)

        lines = [
            "📊 <b>Statistika</b>",
            f"• Obunachilar soni: {total} ta",
            f"• Faol obunachilar: {max(0, total - left)} ta",
            f"• Tark etganlar: {left} ta",
            "",
            "📈 <b>Obunachilar qo'shilishi</b>",
            f"• Oxirgi 24 soat: +{joined(1)} obunachi",
            f"• Oxirgi 7 kun: +{joined(7)} obunachi",
            f"• Oxirgi 30 kun: +{joined(30)} obunachi",
            "",
            "📊 <b>Faollik</b>",
            f"• Oxirgi 24 soatda faol: {active(1)} ta",
            f"• Oxirgi 7 kun faol: {active(7)} ta",
            f"• Oxirgi 30 kun faol: {active(30)} ta",
            "",
            "📥 <b>Yuklanishlar</b>",
            f"• Oxirgi 24 soat: {views(1)} ta",
            f"• Oxirgi 7 kun: {views(7)} ta",
            f"• Oxirgi 30 kun: {views(30)} ta",
            "",
        ]
        # --- Kunlik yangi obunachilar (oxirgi 7 kun) ---
        per_day = {}
        for _d in jl.values():
            per_day[_d] = per_day.get(_d, 0) + 1
        day_lines = []
        for i in range(6, -1, -1):
            dd = now - timedelta(days=i)
            n = per_day.get(dd.strftime("%Y-%m-%d"), 0)
            day_lines.append(f"• {dd.strftime('%d.%m')}: +{n}")
        lines += ["🗓 <b>Kunlik yangi obunachilar</b>"] + day_lines + [""]
        # --- Eng ko'p ko'riladigan kinolar ---
        top_all = sorted(((c, n) for c, n in info["request_counts"].items() if c in info["movies"] and n > 0),
                         key=lambda x: -x[1])[:5]
        if top_all:
            lines.append("🔥 <b>Eng ko'p ko'rilgan kinolar (jami)</b>")
            for i, (c, n) in enumerate(top_all, 1):
                lines.append(f"{i}. {html_escape(kino_title(c, info['movies'][c]))} — kod {c} · 👁 {n}")
            lines.append("")
        top_week = [(c, n) for c, n in kino_rating(info, 7) if c in info["movies"]][:5]
        if top_week:
            lines.append("📅 <b>Oxirgi 7 kunda eng ko'p ko'rilgan</b>")
            for i, (c, n) in enumerate(top_week, 1):
                lines.append(f"{i}. {html_escape(kino_title(c, info['movies'][c]))} — kod {c} · 👁 {n}")
            lines.append("")
        lines += [
            "ℹ️ Kim qaysi kinoni ko'rganini «👁 Kim nimani ko'rgan» bo'limida ko'rasiz.",
            "",
            f"🎬 Kinolar soni: {len(info['movies'])} ta",
        ]
        if is_pro():
            vip_uids = set()
            for uid_s, u in info.get("premium_users", {}).items():
                try:
                    if datetime.fromisoformat(u["until"]) > now:
                        vip_uids.add(uid_s)
                except Exception:
                    pass
            buyers = {uid_s for uid_s, lst in info.get("movie_purchases", {}).items() if lst}
            share = round(len(vip_uids | buyers) * 100 / total) if total else 0
            lines += ["", "💎 <b>PRO Analitika</b>", f"• VIP/xarid ulushi: {share}% obunachi"]
            miss = sorted(info.get("search_miss", {}).items(), key=lambda x: x[1], reverse=True)[:3]
            if miss:
                lines.append("• Qidirilib topilmagan: " + ", ".join(f"«{html_escape(k)}» ({n})" for k, n in miss))
            low = []
            for code, e in info["movies"].items():
                if e.get("access") == "paid":
                    v = info["request_counts"].get(code, 0)
                    sold = info.get("movie_sales", {}).get(code, {}).get("count", 0)
                    if v >= 10 and sold * 20 < v:      # xaridga aylanish 5% dan past
                        low.append((v, code, sold))
            low.sort(reverse=True)
            if low:
                lines.append("• Kam sotib olingan pullik kino: " + ", ".join(
                    f"Kod {c} ({v} ko'rish / {sd} xarid)" for v, c, sd in low[:3]))
            lines += [
                "",
                "<blockquote expandable>💡 <b>Bu nima degani:</b>\n"
                "— <b>VIP/xarid ulushi</b> — obunachilaringizning necha foizi VIP bo'lgan yoki kamida bitta kino sotib olgan. "
                "Pul ishlab topayotganingizning asosiy ko'rsatkichi.\n"
                "— <b>Qidirilib topilmagan</b> — foydalanuvchilar qidirgan, lekin sizda yo'q kino nomlari. "
                "Shularni qo'shsangiz, ko'proq odam botda qoladi.\n"
                "— <b>Kam sotib olingan</b> — bu pullik kinolar ko'p ko'rilgan, lekin kam xarid qilingan. "
                "Balki narxi yuqori yoki tavsifi yetarli emas — tekshirib ko'ring.</blockquote>",
            ]
        uname = (info.get("username") or "").lstrip("@")
        if uname:
            lines += ["", f"🤖 @{uname}"]
        return "\n".join(lines)

