    # ---------- 🖼 Cover (video ko'rinishidagi qora fon o'rniga rasm) ----------
    COVER_REMOVE_BTN = "🗑 Coverni olib tashlash"
    COVER_HOWTO = (
        "Cover rasmini <b>galereyadan yubormang</b> — u qabul qilinmaydi.\n"
        "1) Rasmni avval Telegram «⭐ Sevimlilar» (Saqlangan xabarlar)ga joylang.\n"
        "2) Keyin o'sha rasmni shu yerga <b>uzating (Forward)</b>."
    )

    def cover_apply(code: str, cover_id):
        """Kinoga (serialning barcha qismlariga) cover biriktiradi yoki (None) olib tashlaydi."""
        e = info["movies"].get(code)
        if not e:
            return False
        fids = []
        if e.get("type") == "series":
            fids = [v for v in (e.get("episodes") or {}).values() if isinstance(v, str)]
        elif e.get("file_id"):
            fids = [e["file_id"]]
        vc = info.setdefault("video_covers", {})
        for f in fids:
            if cover_id:
                vc[f] = cover_id
            else:
                vc.pop(f, None)
        if cover_id:
            e["cover"] = cover_id
        else:
            e.pop("cover", None)
        save_data()
        return True

