    @dp.message(CoverFlow.photo, F.photo, F.forward_origin)
    async def cover_photo(message: Message, state: FSMContext):
        # Faqat «Sevimlilar» (Saqlangan xabarlar)dan UZATILGAN rasm qabul qilinadi
        if not is_admin(info, message.from_user.id):
            return
        code = (await state.get_data()).get("cover_code")
