    @dp.callback_query(F.data.startswith("fb_"))
    async def fb_cb(callback: CallbackQuery, state: FSMContext):
        if not is_admin(info, callback.from_user.id):
            await callback.answer()
            return
        parts = callback.data.split("_", 2)
        action = parts[1] if len(parts) > 1 else ""
        arg = parts[2] if len(parts) > 2 else ""
        lst = fb_list()

        def find(bid):
            for i, b in enumerate(lst):
                if b.get("id") == bid:
                    return i, b
            return -1, None

        if action == "menu":
            await state.clear()
            await fb_show(callback)
        elif action == "add":
            if len(lst) >= FB_MAX:
                await callback.answer(f"Ko'pi bilan {FB_MAX} ta tugma qo'shish mumkin.", show_alert=True)
                return
            try:
                await callback.message.edit_text(
                    "➕ <b>Qanday tugma qo'shamiz?</b>\n\nTayyor variantni tanlang yoki o'zingiznikini yarating.",
                    reply_markup=fb_add_kb())
            except TelegramBadRequest:
                pass
        elif action == "p":
            if len(lst) >= FB_MAX:
                await callback.answer(f"Ko'pi bilan {FB_MAX} ta tugma qo'shish mumkin.", show_alert=True)
                return
            if arg == "share":
                if any(b.get("kind") == "share" for b in lst):
                    await callback.answer("«Ulashish» tugmasi allaqachon bor.", show_alert=True)
                    return
                lst.append({"id": uuid.uuid4().hex[:6], "text": "↗️ Ulashish", "kind": "share"})
                save_data()
                await callback.answer("✅ Qo'shildi")
                await fb_show(callback)
            elif arg in FB_PRESETS:
                await state.set_state(FilmButtonFlow.waiting_url)
                await state.update_data(fb_text=FB_PRESETS[arg])
                await callback.message.answer(
                    f"🔗 <b>{FB_PRESETS[arg]}</b> tugmasi uchun havolani yuboring.\n\n"
                    "Masalan: <code>https://instagram.com/akkaunt</code> yoki <code>@kanal_nomi</code>\n"
                    "Bekor qilish: /cancel")
                await callback.answer()
            elif arg == "custom":
                await state.set_state(FilmButtonFlow.waiting_text)
                await callback.message.answer(
                    "✍️ Tugma matnini yozing (masalan: <code>🍿 Yangi kinolar</code>, 40 belgigacha).\n"
                    "Bekor qilish: /cancel")
                await callback.answer()
            else:
                await callback.answer()
        elif action in ("up", "dn"):
            i, _b = find(arg)
            if i >= 0:
                j = i - 1 if action == "up" else i + 1
                if 0 <= j < len(lst):
                    lst[i], lst[j] = lst[j], lst[i]
                    save_data()
            await callback.answer()
            await fb_show(callback)
        elif action == "del":
            i, _b = find(arg)
            if i >= 0:
                lst.pop(i)
                save_data()
            await callback.answer("🗑 O'chirildi")
            await fb_show(callback)
        elif action == "info":
            _i, b = find(arg)
            if b:
                if b.get("kind") == "share":
                    await callback.answer("↗️ Ulashish — foydalanuvchi botni do'stlariga yuboradi.", show_alert=True)
                else:
                    await callback.answer(f"{b.get('text')}\n{b.get('url')}"[:190], show_alert=True)
            else:
                await callback.answer()
        elif action == "cols":
            info["film_buttons_cols"] = 2 if info.get("film_buttons_cols") == 1 else 1
            save_data()
            await callback.answer()
            await fb_show(callback)
        elif action == "toggle":
            info["film_buttons_on"] = not info.get("film_buttons_on", True)
            save_data()
            await callback.answer("🟢 Yoqildi" if info["film_buttons_on"] else "🔴 O'chirildi")
            await fb_show(callback)
        elif action == "clear":
            info["film_buttons"] = []
            save_data()
            await callback.answer("🧹 Tozalandi")
            await fb_show(callback)
        elif action == "prev":
            await get_bot_username(callback.bot)
            rows = film_buttons_rows(fb_share_link())
            if not rows:
                await callback.answer("Ko'rsatish uchun tugma yo'q (yoki bo'limi o'chirilgan).", show_alert=True)
                return
            rate = [InlineKeyboardButton(text=str(n), callback_data="fb_noop") for n in range(1, 6)]
            try:
                await callback.message.answer(
                    "👁 <b>Ko'rinishi</b> (foydalanuvchi filmni shunday ko'radi):\n\n🎬 Kod: 123\n\nNamuna kino tavsifi",
                    reply_markup=InlineKeyboardMarkup(inline_keyboard=[rate] + rows))
            except TelegramBadRequest:
                await callback.message.answer("❌ Tugmalardan birining havolasi noto'g'ri. Uni o'chirib, qayta qo'shing.")
            await callback.answer()
        else:
            await callback.answer()

