    KINO_POST_DELIVER[token] = post_deliver

    async def web_watch(uid: int, code: str) -> str:
        """Veb mini appdagi «Filmni ko'rish» — filmni (yoki VIP/pullik taklifini) foydalanuvchining bot chatiga yuboradi."""
        if not is_active(info) and not is_admin(info, uid):
            return "inactive"
        if is_blocked(uid):
            return "blocked"
        if info.get("maintenance_mode") and not is_admin(info, uid):
            return "maintenance"
        chans = info.get("channels") or {}
        b = _new_bot(token)
        try:
            if chans and not is_admin(info, uid) and not is_premium_user(uid):
                if await get_missing_channels(b, chans, uid):
                    return "channels"
            from aiogram.types import Chat
            msg = Message(message_id=0, date=datetime.now(), chat=Chat(id=uid, type="private")).as_(b)
            await open_movie(msg, uid, code)
            return "ok"
        except Exception as ex:
            logging.warning(f"Veb kino: film yuborilmadi ({uid}, {code}): {ex}")
            return "send_failed"
        finally:
            await _close_bot(b)

    KINO_WATCH[token] = web_watch

    # ---------- 🎲 Tasodifiy kino ----------
    def random_pick_text_kb(uid: int):
        import random
        codes = visible_codes()
        if not codes:
            return None, None
        seen = set((info.get("user_views") or {}).get(str(uid), {}))
        pool = [c for c in codes if c not in seen] or codes
        code = random.choice(pool)
        e = info["movies"].get(code) or {}
        icon = access_icon(uid, code)
        kind = "📺 Serial" if e.get("type") == "series" else "🎬 Kino"
        desc = (e.get("desc") or "").strip()
        text = f"🎲 <b>Tasodifiy tanlov</b>\n\n{kind} {icon}\n\n{html_escape(desc[:350]) if desc else html_escape(movie_title_of(code))}"
        kb = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="🎬 Ko'rish", callback_data=f"kopen_{code}")],
            [InlineKeyboardButton(text="🎲 Boshqasi", callback_data="krand")],
        ])
        return text, kb

    @dp.message(F.text == "🎲 Tasodifiy kino")
    async def kino_random(message: Message, state: FSMContext):
        await state.clear()
        if not await kino_guard(message):
            return
        text, kb = random_pick_text_kb(message.from_user.id)
        if not text:
            await message.answer("🎲 Hozircha kino yo'q.")
            return
        await message.answer(text, reply_markup=kb)

    @dp.callback_query(F.data == "krand")
    async def kino_random_cb(callback: CallbackQuery):
        if not await kino_guard_cb(callback):
            return
        text, kb = random_pick_text_kb(callback.from_user.id)
        if not text:
            await callback.answer("Hozircha kino yo'q.", show_alert=True)
            return
        try:
            await callback.message.edit_text(text, reply_markup=kb)
        except Exception:
            await callback.message.answer(text, reply_markup=kb)
        await callback.answer()

    # ---------- 🏆 Kunlik / haftalik reyting ----------
    def rating_view(uid: int, days: int):
        vis = set(visible_codes())
        ranked = [(c, n) for c, n in kino_rating(info, days) if c in vis][:10]
        title = "🏆 <b>Kunlik reyting</b> (bugun)" if days == 1 else "🏆 <b>Haftalik reyting</b> (oxirgi 7 kun)"
        if ranked:
            medals = ["🥇", "🥈", "🥉"]
            lines = [f"{medals[i] if i < 3 else str(i + 1) + '.'} {html_escape(movie_title_of(c))} — 👁 {n}"
                     for i, (c, n) in enumerate(ranked)]
            text = title + "\n\n" + "\n".join(lines) + "\n\nOchish uchun tanlang 👇"
        else:
            text = title + "\n\nHozircha bu davrda ko'rishlar yo'q."
        toggle = [InlineKeyboardButton(text=("• " if days == 1 else "") + "📅 Bugun", callback_data="krt_1"),
                  InlineKeyboardButton(text=("• " if days == 7 else "") + "🗓 Hafta", callback_data="krt_7")]
        return text, movies_list_kb(uid, [c for c, _ in ranked], extra_rows=[toggle])

