    # ---------- 🏷 Promokodlar (admin) ----------
    def kpm_text() -> str:
        ps = info.get("kpromos") or {}
        if not ps:
            return ("🏷 <b>Promokodlar</b>\n\nHozircha promokod yo'q.\n\n"
                    "Promokod — Premium yoki pullik kinoga chegirma beradi. Obunachi uni «🏷 Promokod» tugmasi orqali kiritadi.")
        lines = ["🏷 <b>Promokodlar</b>\n"]
        for c, p in ps.items():
            used = len(p.get("used_by", []))
            lim = int(p.get("max_uses", 0) or 0)
            lines.append(f"{'🟢' if p.get('active', True) else '⚪️'} <code>{html_escape(c)}</code> — -{p.get('percent', 0)}% · "
                         f"{KPROMO_SCOPES.get(p.get('scope', 'all'), '')} · ishlatilgan: {used}{('/' + str(lim)) if lim else ''}")
        return "\n".join(lines)

    def kpm_kb() -> InlineKeyboardMarkup:
        rows = [[InlineKeyboardButton(text="➕ Yangi promokod", callback_data="kpm_new")]]
        for c, p in (info.get("kpromos") or {}).items():
            rows.append([
                InlineKeyboardButton(text=("⏸ O'chirish: " if p.get("active", True) else "▶️ Yoqish: ") + c, callback_data=f"kpm_t_{c}"),
                InlineKeyboardButton(text="🗑", callback_data=f"kpm_d_{c}"),
            ])
        return InlineKeyboardMarkup(inline_keyboard=rows)

