    @dp.message(KinoPromoAdd.code, F.text)
    async def kpm_code(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        code = re.sub(r"[^A-Za-z0-9_]", "", message.text or "").upper()
        if not (3 <= len(code) <= 20):
            await message.answer("❌ Promokod 3–20 ta lotin harf yoki raqamdan iborat bo'lsin. Qayta yozing:")
            return
        if code in (info.get("kpromos") or {}):
            await message.answer("⚠️ Bu nomli promokod bor. Boshqa nom yozing:")
            return
        await state.update_data(kpm_code=code)
        await state.set_state(KinoPromoAdd.percent)
        await message.answer("💯 Chegirma foizini yozing (1 dan 90 gacha), masalan: <code>20</code>")

    @dp.message(KinoPromoAdd.percent, F.text)
    async def kpm_percent(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        digits = re.sub(r"\D", "", message.text or "")
        if not digits or not (1 <= int(digits) <= 90):
            await message.answer("❌ 1 dan 90 gacha raqam yozing:")
            return
        await state.update_data(kpm_percent=int(digits))
        rows = [[InlineKeyboardButton(text=v, callback_data=f"kpm_s_{k}")] for k, v in KPROMO_SCOPES.items()]
        await message.answer("📌 Promokod nimaga qo'llansin?", reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))

    @dp.callback_query(F.data.startswith("kpm_s_"))
    async def kpm_scope(callback: CallbackQuery, state: FSMContext):
        if not is_admin(info, callback.from_user.id):
            await callback.answer()
            return
        scope = callback.data.split("_", 2)[2]
        if scope not in KPROMO_SCOPES or (await state.get_data()).get("kpm_percent") is None:
            await callback.answer("Jarayon eskirgan. Qaytadan boshlang.", show_alert=True)
            return
        await state.update_data(kpm_scope=scope)
        await state.set_state(KinoPromoAdd.limit)
        await callback.message.answer("🔢 Necha kishi ishlata oladi? Raqam yozing (<code>0</code> — cheklovsiz):")
        await callback.answer()

    @dp.message(KinoPromoAdd.limit, F.text)
    async def kpm_limit(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        digits = re.sub(r"\D", "", message.text or "")
        if not digits:
            await message.answer("❌ Raqam yozing (0 — cheklovsiz):")
            return
        d = await state.get_data()
        code = d.get("kpm_code")
        if not code:
            await state.clear()
            await message.answer("Jarayon eskirgan. Qaytadan boshlang.")
            return
        info.setdefault("kpromos", {})[code] = {
            "percent": int(d.get("kpm_percent", 10)), "scope": d.get("kpm_scope", "all"),
            "max_uses": int(digits), "used_by": [], "active": True,
            "created": kino_now().strftime("%Y-%m-%d"),
        }
        save_data()
        await state.clear()
        await message.answer(f"✅ Promokod yaratildi: <code>{code}</code> (-{d.get('kpm_percent')}%)")
        await message.answer(kpm_text(), reply_markup=kpm_kb())

    @dp.callback_query(F.data.startswith("kpm_t_"))
    async def kpm_toggle(callback: CallbackQuery):
        if not is_admin(info, callback.from_user.id):
            await callback.answer()
            return
        p = (info.get("kpromos") or {}).get(callback.data[6:])
        if p is None:
            await callback.answer("Topilmadi.", show_alert=True)
            return
        p["active"] = not p.get("active", True)
        save_data()
        try:
            await callback.message.edit_text(kpm_text(), reply_markup=kpm_kb())
        except Exception:
            pass
        await callback.answer("Saqlandi")

    @dp.callback_query(F.data.startswith("kpm_d_"))
    async def kpm_delete(callback: CallbackQuery):
        if not is_admin(info, callback.from_user.id):
            await callback.answer()
            return
        info.get("kpromos", {}).pop(callback.data[6:], None)
        save_data()
        try:
            await callback.message.edit_text(kpm_text(), reply_markup=kpm_kb())
        except Exception:
            pass
        await callback.answer("O'chirildi")

    # ---------- 👁 Kim nimani ko'rgan (admin) ----------
    def user_link(uid) -> str:
        return f'<a href="tg://user?id={uid}">{uid}</a>'

    def view_line(row) -> str:
        u, c, ts, ep = row[0], row[1], row[2], (row[3] if len(row) > 3 else 0)
        m = info["movies"].get(c) or {}
        ep_s = f" · {ep}-qism" if ep else ""
        return f"{ts[5:]} · {user_link(u)} → {html_escape(kino_title(c, m)) if m else 'Kod ' + str(c)} (kod {c}{ep_s})"

    @dp.message(F.text == "👁 Kim nimani ko'rgan")
    async def kino_views_panel(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        await state.clear()
        log = info.get("view_log") or []
        if not log:
            await message.answer("👁 <b>Kim nimani ko'rgan</b>\n\nHozircha ma'lumot yo'q. Obunachilar kino ko'ra boshlagach, shu yerda ko'rinadi.")
            return
        lines = [view_line(r) for r in reversed(log[-20:])]
        await state.set_state(KinoViewsQ.query)
        await message.answer(
            "👁 <b>Oxirgi 20 ta ko'rish</b>\n\n" + "\n".join(lines) +
            "\n\n🔎 Batafsil: <b>foydalanuvchi ID</b> sini yuboring — u nimalarni ko'rgan; yoki <b>kino kodini</b> yuboring — uni kimlar ko'rgan.\n"
            "Chiqish: /bekor", disable_web_page_preview=True)

    @dp.message(KinoViewsQ.query, Command("bekor"))
    async def kino_views_cancel(message: Message, state: FSMContext):
        await state.clear()
        await message.answer("✅ Chiqildi.")

    @dp.message(KinoViewsQ.query, F.text)
    async def kino_views_query(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        q = (message.text or "").strip()
        if q.startswith("/") or not q.isdigit():
            await state.clear()
            if not q.startswith("/"):
                await message.answer("❌ Faqat raqam (ID yoki kino kodi) yuboring. Bo'limni qayta oching.")
            return
        log = info.get("view_log") or []
        if len(q) >= 7:       # foydalanuvchi ID
            uid = int(q)
            mine = [r for r in log if r[0] == uid]
            summary = (info.get("user_views") or {}).get(str(uid), {})
            if not mine and not summary:
                await message.answer("Bu foydalanuvchi hali kino ko'rmagan (yoki ID noto'g'ri).")
                await state.clear()
                return
            top = sorted(summary.items(), key=lambda x: -x[1])[:10]
            txt = (f"👤 {user_link(uid)} — jami <b>{sum(summary.values())}</b> ta ko'rish\n\n"
                   "🎬 <b>Eng ko'p ko'rgani:</b>\n" +
                   "\n".join(f"• {html_escape(kino_title(c, info['movies'].get(c) or {}))} (kod {c}) — {n} marta" for c, n in top) +
                   "\n\n🕒 <b>Oxirgilari:</b>\n" + "\n".join(view_line(r) for r in reversed(mine[-10:])))
        else:                  # kino kodi
            rows = [r for r in log if r[1] == q]
            m = info["movies"].get(q)
            if not rows:
                await message.answer("Bu kodli kinoni hali hech kim ko'rmagan (yoki kod noto'g'ri).")
                await state.clear()
                return
            uniq = []
            for r in reversed(rows):
                if r[0] not in uniq:
                    uniq.append(r[0])
            txt = (f"🎬 <b>{html_escape(kino_title(q, m or {}))}</b> (kod {q})\n"
                   f"👁 Jami: {info['request_counts'].get(q, len(rows))} ta · alohida odam: {len(set(r[0] for r in rows))} ta\n\n"
                   "🕒 <b>Oxirgi ko'rganlar:</b>\n" + "\n".join(view_line(r) for r in reversed(rows[-15:])))
        await state.clear()
        await message.answer(txt[:4000], disable_web_page_preview=True)

    # ---------- ⏰ Rejalashtirilgan postlar ----------
    @dp.message(F.text == "⏰ Rejalashtirish")
    async def post_schedule_start(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id) or not await post_need_channel(message, state):
            return
        d = await state.get_data()
        if not (d.get("pst_text") or d.get("pst_file")):
            await message.answer("❌ Avval post matni yoki videosini qo'shing.", reply_markup=postbuild_kb())
            return
        await state.set_state(PostBuild.schedule)
        now = kino_now()
        await message.answer(
            "⏰ <b>Post qachon chiqsin?</b> (Toshkent vaqti)\n\n"
            f"Hozir: <code>{now.strftime('%d.%m.%Y %H:%M')}</code>\n\n"
            "Namunalar:\n"
            "• <code>bugun 18:30</code>\n"
            "• <code>ertaga 09:00</code>\n"
            "• <code>15.10.2026 20:00</code>\n"
            "• <code>2026-10-15 20:00</code>\n\n"
            "Orqaga qaytish: «◀️ Orqaga»", reply_markup=postbuild_kb())

    @dp.message(PostBuild.schedule, F.text)
    async def post_schedule_save(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        when = kino_parse_when(message.text)
        if not when:
            await message.answer("❌ Vaqtni tushunmadim. Masalan: <code>bugun 18:30</code> yoki <code>15.10.2026 20:00</code>")
            return
        if when <= kino_now() + timedelta(seconds=45):
            await message.answer("❌ Bu vaqt o'tib ketgan. Kelajakdagi vaqtni yozing:")
            return
        d = await state.get_data()
        lst = info.setdefault("scheduled_posts", [])
        if sum(1 for p in lst if p.get("status") == "pending") >= 30:
            await message.answer("❌ Rejalashtirilgan postlar juda ko'p (30 ta). Avval ba'zilarini bekor qiling.")
            return
        lst.append({
            "id": uuid.uuid4().hex[:6], "chat": str(d["pst_chat"]), "title": d.get("pst_title") or "",
            "at": when.strftime("%Y-%m-%d %H:%M"), "status": "pending", "by": message.from_user.id,
            "post": {"kind": d.get("pst_kind"), "file_id": d.get("pst_file"),
                     "text": d.get("pst_text"), "rows": d.get("pst_rows") or []},
        })
        save_data()
        await state.clear()
        await message.answer(
            f"✅ Post rejalashtirildi!\n\n📢 Qayerga: «{html_escape(d.get('pst_title') or '')}»\n"
            f"⏰ Vaqt: <b>{when.strftime('%d.%m.%Y %H:%M')}</b>\n\n"
            "Ro'yxat va bekor qilish: «⏰ Rejalashtirilgan postlar».", reply_markup=ultra_admin_kb())

    def sched_text_kb():
        lst = [p for p in (info.get("scheduled_posts") or []) if p.get("status") == "pending"]
        lst.sort(key=lambda p: p.get("at", ""))
        if not lst:
            return ("⏰ <b>Rejalashtirilgan postlar</b>\n\nHozircha yo'q.\n\n"
                    "Yangisi: «📮 Postlar» → kanal → post tayyorlang → «⏰ Rejalashtirish»."), None
        lines = ["⏰ <b>Rejalashtirilgan postlar</b>\n"]
        rows = []
        for p in lst:
            try:
                at = datetime.strptime(p["at"], "%Y-%m-%d %H:%M").strftime("%d.%m %H:%M")
            except Exception:
                at = p.get("at", "")
            kind = {"video": "🎬", "photo": "🖼", "animation": "🎞"}.get((p.get("post") or {}).get("kind"), "📝")
            lines.append(f"{kind} {at} → «{html_escape(p.get('title') or '')}»")
            rows.append([InlineKeyboardButton(text=f"🗑 Bekor qilish: {at}", callback_data=f"pst_sdel_{p['id']}")])
        return "\n".join(lines), InlineKeyboardMarkup(inline_keyboard=rows)

    @dp.message(F.text == "⏰ Rejalashtirilgan postlar")
    async def sched_list(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        await state.clear()
        text, kb = sched_text_kb()
        await message.answer(text, reply_markup=kb)

    @dp.callback_query(F.data.startswith("pst_sdel_"))
    async def sched_cancel(callback: CallbackQuery):
        if not is_admin(info, callback.from_user.id):
            await callback.answer()
            return
        pid = callback.data[9:]
        for p in info.get("scheduled_posts") or []:
            if p.get("id") == pid and p.get("status") == "pending":
                p["status"] = "cancelled"
        save_data()
        text, kb = sched_text_kb()
        try:
            await callback.message.edit_text(text, reply_markup=kb)
        except Exception:
            pass
        await callback.answer("Bekor qilindi")

