def setup_openbudget_bot(dp: Dispatcher, token: str):
    info = data["bots"][token]
    admin_id = info["admin_id"]
    info["stats"].setdefault("requests", 0)
    info.setdefault("users", [])
    info.setdefault("blocked_users", [])
    info.setdefault("ob_projects", {})
    info.setdefault("ob_next_id", 1)
    info.setdefault("ob_url", "https://openbudget.uz")
    info.setdefault("ob_deadline", "")
    info.setdefault("ob_remind", [])
    info.setdefault("ob_feedback", {})
    info.setdefault("ob_referrals", {})
    info.setdefault("ob_ref_by", {})
    info.setdefault("ob_cats", list(OB_DEFAULT_CATS))
    info.setdefault("ob_names", {})
    info.setdefault("ob_join", {})
    info.setdefault("ob_quiz_best", {})
    info.setdefault("ob_welcome", "🗳 <b>Open Budget yordamchi boti</b>\n\nLoyihalarni ko'ring, rasmiy saytda o'zingiz ovoz bering va do'stlaringizni xabardor qiling.")
    info.setdefault("ob_rules", (
        "❓ <b>Qanday ovoz beriladi?</b>\n\n"
        "1️⃣ «📋 Loyihalar» dan loyihani tanlang.\n"
        "2️⃣ «🗳 Rasmiy saytda ovoz berish» tugmasini bosing.\n"
        "3️⃣ Telefon raqamingizni va SMS kodni <b>faqat rasmiy saytda</b> kiriting.\n"
        "4️⃣ Ovoz bergach, shu yerda «✅ Ovoz berdim» ni bosing."))
    setup_subscription_handlers(dp, token, admin_id)
    setup_admin_management(dp, token)
    setup_generic_panel(dp, token)

    def esc(x):
        return html_escape(str(x))

    def today_s():
        return datetime.now().strftime("%Y-%m-%d")

    def PR():
        return info["ob_projects"]

    def cats():
        return info["ob_cats"]

    def regions():
        return sorted({p["region"] for p in PR().values() if p.get("region")})

    def money(n):
        try:
            n = int(n)
        except Exception:
            n = 0
        return (f"{n:,}".replace(",", " ") + " so'm") if n else "—"

    def admin_ids():
        return info.get("admin_ids", [admin_id])

    def user_kb():
        return ReplyKeyboardMarkup(keyboard=bp_pub_row(info) + [
            [KeyboardButton(text="🗳 Ovoz berish"), KeyboardButton(text="📋 Loyihalar")],
            [KeyboardButton(text="🔎 Qidirish"), KeyboardButton(text="🏷 Kategoriyalar")],
            [KeyboardButton(text="⭐ Sevimlilar"), KeyboardButton(text="🏆 Reyting")],
            [KeyboardButton(text="📅 Muddat"), KeyboardButton(text="🔔 Eslatma")],
            [KeyboardButton(text="👥 Do'stlarni taklif"), KeyboardButton(text="🧠 Viktorina")],
            [KeyboardButton(text="❓ Yo'riqnoma"), KeyboardButton(text="🛡 Xavfsizlik")],
            [KeyboardButton(text="📞 Murojaat"), KeyboardButton(text="ℹ️ Bot haqida")],
        ] + get_global_button_rows(), resize_keyboard=True)

    def admin_kb():
        return ReplyKeyboardMarkup(keyboard=bp_panel_row(info) + [
            [KeyboardButton(text="➕ Loyiha qo'shish"), KeyboardButton(text="📝 Loyihalarni boshqarish")],
            [KeyboardButton(text="📣 Xabar yuborish"), KeyboardButton(text="📊 Statistika")],
            [KeyboardButton(text="📅 Muddat belgilash"), KeyboardButton(text="🔗 Rasmiy havola")],
            [KeyboardButton(text="✍️ Matnlar"), KeyboardButton(text="📥 Murojaatlar")],
            [KeyboardButton(text="🚫 Bloklash"), KeyboardButton(text="📤 Eksport")],
            [KeyboardButton(text="🔔 Eslatma yuborish"), KeyboardButton(text="👁 Foydalanuvchi menyusi")],
            [KeyboardButton(text="📡 Majburiy obuna"), KeyboardButton(text="👤 Adminlar")],
        ] + get_global_button_rows(), resize_keyboard=True)

    cancel_kb = ReplyKeyboardMarkup(keyboard=[[KeyboardButton(text="❌ Bekor qilish")]], resize_keyboard=True)

    async def cancelled(message: Message, state: FSMContext) -> bool:
        if message.text and message.text.strip() == "❌ Bekor qilish":
            await state.clear()
            await message.answer("❌ Bekor qilindi.", reply_markup=admin_kb() if is_admin(info, message.from_user.id) else user_kb())
            return True
        return False

    async def uname(bot) -> str:
        if not info.get("username"):
            try:
                info["username"] = (await bot.get_me()).username or ""
                save_data()
            except Exception:
                return ""
        return info.get("username", "")

    # ---------- Middleware: bloklash, faollik, foydalanuvchini yozib borish ----------
    class OBGate(BaseMiddleware):
        async def __call__(self, handler, event, data_):
            user = getattr(event, "from_user", None)
            if user:
                uid = user.id
                if not is_admin(info, uid):
                    if uid in info["blocked_users"]:
                        try:
                            if isinstance(event, CallbackQuery):
                                await event.answer("🚫 Siz bloklangansiz.", show_alert=True)
                            else:
                                await event.answer("🚫 Siz bloklangansiz.")
                        except Exception:
                            pass
                        return
                    if isinstance(event, Message) and not await check_active(event, info, admin_id):
                        return
                is_new = uid not in info["users"]
                if is_new:
                    info["users"].append(uid)
                    info["ob_join"][str(uid)] = today_s()
                info["ob_names"][str(uid)] = ("@" + user.username) if user.username else (user.full_name or "")
                if isinstance(event, Message):
                    info["stats"]["requests"] = info["stats"].get("requests", 0) + 1
                    txt = event.text or ""
                    if is_new and txt.startswith("/start ref_"):
                        try:
                            ref = int(txt.split("ref_", 1)[1].strip())
                        except Exception:
                            ref = 0
                        if ref and ref != uid and ref in info["users"]:
                            info["ob_ref_by"][str(uid)] = ref
                            info["ob_referrals"].setdefault(str(ref), []).append(uid)
                            try:
                                await event.bot.send_message(ref, "🎉 Sizning havolangiz orqali yangi foydalanuvchi qo'shildi!")
                            except Exception:
                                pass
                if is_new:
                    save_data()
            return await handler(event, data_)

    dp.message.outer_middleware(OBGate())
    dp.callback_query.outer_middleware(OBGate())

    # ---------- Muddat ----------
    def deadline_dt():
        s = info.get("ob_deadline", "")
        try:
            return datetime.fromisoformat(s) if s else None
        except Exception:
            return None

    def deadline_text():
        d = deadline_dt()
        if not d:
            return "📅 Ovoz berish muddati hali belgilanmagan."
        rem = d - datetime.now()
        if rem.total_seconds() <= 0:
            return f"⌛️ Ovoz berish muddati tugagan ({d:%d.%m.%Y %H:%M})."
        return (f"📅 Tugash vaqti: <b>{d:%d.%m.%Y %H:%M}</b>\n"
                f"⏳ Qoldi: <b>{rem.days} kun {rem.seconds // 3600} soat {rem.seconds % 3600 // 60} daqiqa</b>")

    # ---------- Loyiha kartasi ----------
    def card_text(p):
        return (
            f"🏛 <b>{esc(p['title'])}</b>\n"
            f"🏷 {esc(p.get('category') or '—')}   📍 {esc(p.get('region') or '—')}\n"
            f"💰 Byudjet: <b>{money(p.get('budget'))}</b>\n\n"
            f"{esc(p.get('desc') or '')}\n\n"
            f"✅ Ovoz berdim: <b>{len(p['voted'])}</b>  ⭐ Sevimli: <b>{len(p['favs'])}</b>  👁 {p.get('views', 0)}\n"
            f"🆔 Loyiha raqami: <code>{p['id']}</code>")

    def card_kb(p, uid):
        rows = []
        if str(p.get("link", "")).startswith("http"):
            rows.append([InlineKeyboardButton(text="🗳 Rasmiy saytda ovoz berish", url=p["link"])])
        fav, voted = uid in p["favs"], uid in p["voted"]
        rows.append([
            InlineKeyboardButton(text="💔 Sevimlidan olish" if fav else "⭐ Sevimlilarga", callback_data=f"obf_{p['id']}"),
            InlineKeyboardButton(text="↩️ Belgini olish" if voted else "✅ Ovoz berdim", callback_data=f"obv_{p['id']}"),
        ])
        rows.append([InlineKeyboardButton(text="📤 Ulashish", callback_data=f"obs_{p['id']}")])
        return InlineKeyboardMarkup(inline_keyboard=rows)

    async def send_card(message: Message, p, uid):
        p["views"] = p.get("views", 0) + 1
        save_data()
        if p.get("photo"):
            try:
                await message.answer_photo(p["photo"], caption=card_text(p)[:1024], reply_markup=card_kb(p, uid))
                return
            except Exception:
                pass
        await message.answer(card_text(p), reply_markup=card_kb(p, uid))

    async def refresh(cb: CallbackQuery, p):
        try:
            if cb.message.photo:
                await cb.message.edit_caption(caption=card_text(p)[:1024], reply_markup=card_kb(p, cb.from_user.id))
            else:
                await cb.message.edit_text(card_text(p), reply_markup=card_kb(p, cb.from_user.id))
        except TelegramBadRequest:
            pass

    # ---------- Ro'yxatlar ----------
    PAGE = 8
    lastq = {}

    def ids_for(mode, arg, uid):
        ps = list(PR().values())
        if mode == "cat":
            c = cats()[int(arg)] if int(arg) < len(cats()) else ""
            ps = [p for p in ps if p.get("category") == c]
        elif mode == "reg":
            r = regions()
            rg = r[int(arg)] if int(arg) < len(r) else ""
            ps = [p for p in ps if p.get("region") == rg]
        elif mode == "fav":
            ps = [p for p in ps if uid in p["favs"]]
        elif mode == "top":
            ps = sorted(ps, key=lambda p: -len(p["voted"]))
            return [p["id"] for p in ps]
        elif mode == "q":
            return [i for i in lastq.get(uid, []) if i in PR()]
        return [p["id"] for p in sorted(ps, key=lambda p: -int(p["id"]))]

    def list_kb(ids, mode, arg, page):
        chunk = ids[page * PAGE:(page + 1) * PAGE]
        rows = [[InlineKeyboardButton(text=f"{PR()[i]['title'][:34]} · ✅{len(PR()[i]['voted'])}", callback_data=f"obp_{i}")] for i in chunk]
        nav = []
        if page > 0:
            nav.append(InlineKeyboardButton(text="◀️", callback_data=f"obpg_{mode}_{arg}_{page - 1}"))
        if (page + 1) * PAGE < len(ids):
            nav.append(InlineKeyboardButton(text="▶️", callback_data=f"obpg_{mode}_{arg}_{page + 1}"))
        if nav:
            rows.append(nav)
        if mode == "all":
            rows.append([InlineKeyboardButton(text="🏷 Kategoriya", callback_data="obcats"), InlineKeyboardButton(text="📍 Hudud", callback_data="obregs")])
        return InlineKeyboardMarkup(inline_keyboard=rows)

    async def show_list(event, mode, arg=0, page=0, ids=None, title="📋 <b>Loyihalar</b>"):
        uid = event.from_user.id
        ids = ids if ids is not None else ids_for(mode, arg, uid)
        if not ids:
            txt = "Hozircha loyiha topilmadi."
            kb = list_kb([], mode, arg, 0) if mode == "all" else None
        else:
            txt = f"{title}\nJami: {len(ids)} ta"
            kb = list_kb(ids, mode, arg, page)
        if isinstance(event, CallbackQuery):
            try:
                await event.message.edit_text(txt, reply_markup=kb)
            except TelegramBadRequest:
                await event.message.answer(txt, reply_markup=kb)
            await event.answer()
        else:
            await event.answer(txt, reply_markup=kb)

    # ---------- /start ----------
    @dp.message(Command("start"))
    async def mstart(message: Message, state: FSMContext = None):
        if state:
            await state.clear()
        uid = message.from_user.id
        parts = (message.text or "").split(maxsplit=1)
        arg = parts[1].strip() if len(parts) > 1 else ""
        if is_admin(info, uid):
            await message.answer(f"🏛 <b>Open Budget bot — boshqaruv</b>\n\nLoyihalar: {len(PR())} • Foydalanuvchilar: {len(info['users'])}", reply_markup=admin_kb())
            return
        if not await require_subscription(message, info, admin_id):
            return
        await message.answer(info["ob_welcome"] + "\n\n" + deadline_text(), reply_markup=user_kb())
        if arg.startswith("p_") and arg[2:] in PR():
            await send_card(message, PR()[arg[2:]], uid)

    setup_global_buttons_handler(dp, lambda m, s: mstart(m, s))

