    async def fb_save(message: Message, state: FSMContext):
        if await cancelled(message, state):
            return
        text = (message.text or "").strip()
        if not text:
            await message.answer("Matn yuboring.")
            return
        fid = str(len(info["ob_feedback"]) + 1)
        info["ob_feedback"][fid] = {"uid": message.from_user.id, "name": info["ob_names"].get(str(message.from_user.id), ""),
                                    "text": text[:2000], "date": datetime.now().strftime("%Y-%m-%d %H:%M"), "answered": False}
        save_data()
        await state.clear()
        await message.answer("✅ Murojaatingiz yuborildi.", reply_markup=user_kb())
        for a in admin_ids():
            try:
                await message.bot.send_message(a, f"📞 <b>Yangi murojaat #{fid}</b>\n👤 {esc(info['ob_feedback'][fid]['name'])} (<code>{message.from_user.id}</code>)\n\n{esc(text[:2000])}",
                                               reply_markup=InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="↩️ Javob berish", callback_data=f"obr_{fid}")]]))
            except Exception:
                pass

