    async def add_cat(callback: CallbackQuery, state: FSMContext):
        i = int(callback.data.split("_")[1])
        await state.update_data(category=cats()[i] if i < len(cats()) else "")
        await callback.message.answer("📍 Hudud (tuman/mahalla) nomini yozing:")
        await state.set_state(OBAdd.region)
