    async def panel_call(**params):
        if not api_ready():
            raise RuntimeError("API sozlanmagan")
        payload = {"key": info["nk_api_key"], **params}
        async with httpx.AsyncClient(timeout=30, follow_redirects=True) as c:
            r = await c.post(info["nk_api_url"], data=payload)
            r.raise_for_status()
            js = r.json()
        if isinstance(js, dict) and js.get("error"):
            raise RuntimeError(str(js["error"]))
        return js

    async def sync_services() -> int:
        js = await panel_call(action="services")
        if not isinstance(js, list):
            raise RuntimeError("Panel xizmatlar ro'yxatini qaytarmadi")
        old = info["nk_services"]
        new = {}
        for it in js[:4000]:
            try:
                sid = str(it["service"])
                prev = old.get(sid, {})
                new[sid] = {
                    "name": str(it.get("name", ""))[:120], "category": str(it.get("category") or "Boshqa")[:80],
                    "rate": float(it.get("rate", 0)), "currency": "USD", "min": int(float(it.get("min", 1))),
                    "max": int(float(it.get("max", 1))), "enabled": prev.get("enabled", True),
                    "custom_price": prev.get("custom_price"), "source": "panel", "refill": bool(it.get("refill")),
                }
            except Exception:
                continue
        for sid, s in old.items():
            if s.get("source") == "manual":
                new[sid] = s
        info["nk_services"] = new
        save_data()
        return len(new)

    def order_card(oid: str, o: dict) -> str:
        lines = [
            f"{NK_STATUS_EMOJI.get(o['status'], '❔')} <b>Buyurtma #{oid}</b>", "",
            f"🛍 {esc(o['name'])}", f"🔗 {esc(o['link'])}", f"🔢 Miqdor: {o['qty']:,}",
            f"💰 Narxi: {som(o['price'])} so'm",
            f"📌 Holati: <b>{NK_STATUS_LABEL.get(o['status'], o['status'])}</b>",
            f"🕒 {o['created_at'][:16].replace('T', ' ')}",
        ]
        if o.get("refund_amount"):
            lines.append(f"↩️ Qaytarildi: {som(o['refund_amount'])} so'm")
        return "\n".join(lines)

    async def notify_admins(bot, text, kb=None):
        for aid in info.get("admin_ids", [admin_id]):
            try:
                await bot.send_message(aid, text, reply_markup=kb)
            except Exception as e:
                logging.error(f"Nakrutka: adminga xabar yuborilmadi ({aid}): {e}")

    async def refresh_order(oid: str, bot):
        o = info["nk_orders"].get(oid)
        if not o or not o.get("panel_id") or o["status"] not in NK_ACTIVE:
            return
        js = await panel_call(action="status", order=o["panel_id"])
        if not isinstance(js, dict):
            return
        new = nk_map_status(js.get("status"))
        try:
            o["remains"] = int(float(js.get("remains", 0)))
        except Exception:
            pass
        if new == o["status"]:
            return
        o["status"] = new
        o["updated_at"] = datetime.now().isoformat(timespec="seconds")
        if new in ("bekor", "qisman") and not o.get("refunded"):
            if new == "bekor":
                refund = int(o["price"])
            else:
                remains = min(max(int(o.get("remains", 0)), 0), int(o["qty"]))
                refund = int(o["price"] * remains / max(1, int(o["qty"])))
            o["refunded"] = True
            if refund > 0:
                add_bal(o["uid"], refund, f"Qaytarildi #{oid}")
                o["refund_amount"] = refund
                st["revenue"] -= refund
        save_data()
        if new in ("bajarildi", "bekor", "qisman"):
            txt = f"{NK_STATUS_EMOJI[new]} <b>Buyurtma #{oid}</b> — {NK_STATUS_LABEL[new]}"
            if o.get("refund_amount"):
                txt += f"\n↩️ Hisobingizga {som(o['refund_amount'])} so'm qaytarildi."
            try:
                await bot.send_message(o["uid"], txt)
            except Exception:
                pass

    async def place_order(bot, uid: int, uname: str, sid: str, link: str, qty: int):
        """(ok, xabar, order|price) qaytaradi. xabar == 'LOW' bo'lsa balans yetmaydi."""
        s = info["nk_services"].get(sid)
        if not s or not s.get("enabled", True):
            return False, "❌ Xizmat topilmadi yoki vaqtincha o'chirilgan.", None
        if qty < int(s["min"]) or qty > int(s["max"]):
            return False, f"❌ Miqdor {int(s['min']):,} – {int(s['max']):,} oralig'ida bo'lishi kerak.", None
        price = calc_price(s, qty)
        if bal(uid) < price:
            return False, "LOW", price
        oid = uuid.uuid4().hex[:8]
        add_bal(uid, -price, f"Buyurtma #{oid}")
        order = {"uid": uid, "uname": uname, "sid": sid, "name": s["name"], "link": link, "qty": qty,
                 "price": price, "cost": calc_cost(s, qty), "status": "kutilmoqda", "panel_id": None,
                 "created_at": datetime.now().isoformat(timespec="seconds")}
        use_panel = api_ready() and s.get("source") == "panel"
        if use_panel:
            try:
                js = await panel_call(action="add", service=sid, link=link, quantity=qty)
                pid = js.get("order") if isinstance(js, dict) else None
                if not pid:
                    raise RuntimeError("Panel buyurtma ID qaytarmadi")
                order["panel_id"] = str(pid)
            except Exception as e:
                add_bal(uid, price, f"Qaytarildi (xato) #{oid}")
                save_data()
                logging.error(f"Nakrutka: panelga buyurtma yuborilmadi: {e}")
                await notify_admins(bot, f"⚠️ <b>Panelga buyurtma yuborilmadi</b>\nXizmat: {esc(s['name'])}\nXato: {esc(str(e)[:300])}")
                return False, "❌ Buyurtmani hozir yuborib bo'lmadi. Mablag'ingiz qaytarildi, birozdan so'ng urinib ko'ring.", None
        info["nk_orders"][oid] = order
        st["orders"] += 1
        st["revenue"] += price
        info["nk_spent"][str(uid)] = int(info["nk_spent"].get(str(uid), 0)) + price
        save_data()
        if not use_panel:
            kb = InlineKeyboardMarkup(inline_keyboard=[[
                InlineKeyboardButton(text="✅ Bajarildi", callback_data=f"nkoa_{oid}"),
                InlineKeyboardButton(text="❌ Rad etish", callback_data=f"nkor_{oid}"),
            ]])
            await notify_admins(bot, "🆕 <b>Yangi buyurtma (qo'lda)</b>\n\n" + order_card(oid, order)
                                + f"\n👤 {esc(uname)} (<code>{uid}</code>)", kb)
        return True, "", order

