    @dp.message(Command("start"))
    async def nk_start(message: Message, state: FSMContext):
        await state.clear()
        uid = message.from_user.id
        if uid not in info["users"]:
            info["users"].append(uid)
            args = (message.text or "").split(maxsplit=1)
            if len(args) > 1 and args[1].startswith("ref_"):
                try:
                    ref = int(args[1][4:])
                except ValueError:
                    ref = None
                if ref and ref != uid and ref in info["users"] and str(uid) not in info["nk_ref_by"]:
                    info["nk_ref_by"][str(uid)] = ref
                    try:
                        await message.bot.send_message(ref, "🎉 Sizning havolangiz orqali yangi foydalanuvchi qo'shildi! "
                                                            "U hisobini to'ldirganda sizga bonus beriladi.")
                    except Exception:
                        pass
            save_data()
        if not await guard(message):
            return
        if is_admin(info, uid):
            await message.answer("🚀 <b>Nakrutka bot boshqaruvi</b>\n\nPastdagi menyudan foydalaning 👇", reply_markup=admin_kb())
            return
        welcome = S.get("welcome") or (
            f"🚀 <b>{esc(info.get('name') or 'Nakrutka bot')}</b>\n\n"
            "Instagram, TikTok, Telegram, YouTube va boshqa tarmoqlar uchun obunachi, layk va ko'rish xizmatlari — "
            "tez, arzon va ishonchli.\n\nPastdagi menyudan foydalaning 👇")
        await message.answer(f"{welcome}\n\n💰 Balansingiz: <b>{som(bal(uid))} so'm</b>", reply_markup=user_kb())

