        if not svcs:
            await say(event, "😔 Hozircha xizmatlar qo'shilmagan. Birozdan so'ng qayta urinib ko'ring.")
            return
        counts: dict = {}
        for s in svcs.values():
            k = nk_platform_of(s)
            counts[k] = counts.get(k, 0) + 1
        btns = [InlineKeyboardButton(text=f"{label} ({counts[key]})", callback_data=f"nkpl_{key}")
                for key, label, _ in NK_PLATFORMS if key in counts]
        rows = [btns[i:i + 2] for i in range(0, len(btns), 2)]
        await say(event, "🛍 <b>Xizmatlar katalogi</b>\n\nTarmoqni tanlang 👇", reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))

