    @dp.callback_query(F.data.startswith("nkpl_"))
    async def nk_platform_cb(callback: CallbackQuery):
        if not await guard(callback):
            return
        key = callback.data[5:]
        if key == "all":
            await show_platforms(callback)
            return
        cats: dict = {}
        for s in enabled_services().values():
            if nk_platform_of(s) == key:
                c = s.get("category") or "Boshqa"
                cats[c] = cats.get(c, 0) + 1
        if not cats:
            await callback.answer("Bu bo'limda xizmat yo'q", show_alert=True)
            return
        rows = [[InlineKeyboardButton(text=f"{c[:40]} ({n})", callback_data=f"nkct_{key}_{nk_cat_hash(c)}_0")]
                for c, n in sorted(cats.items())[:40]]
        rows.append([InlineKeyboardButton(text="⬅️ Tarmoqlar", callback_data="nkpl_all")])
        await say(callback, f"{nk_plat_label(key)}\n\nBo'limni tanlang 👇", reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))

    @dp.callback_query(F.data.startswith("nkct_"))
    async def nk_category_cb(callback: CallbackQuery):
        if not await guard(callback):
            return
        try:
            _, key, h, page = callback.data.split("_")
            page = int(page)
        except ValueError:
            await callback.answer()
            return
        items = [(sid, s) for sid, s in enabled_services().items()
                 if nk_platform_of(s) == key and nk_cat_hash(s.get("category") or "Boshqa") == h]
        items.sort(key=lambda x: price_1000(x[1]))
        if not items:
            await callback.answer("Xizmat topilmadi", show_alert=True)
            return
        pages = max(1, math.ceil(len(items) / NK_PAGE))
        page = min(max(page, 0), pages - 1)
        chunk = items[page * NK_PAGE:(page + 1) * NK_PAGE]
        rows = [[InlineKeyboardButton(text=f"{s['name'][:34]} — {som(price_1000(s))}", callback_data=f"nksv_{sid}")]
                for sid, s in chunk]
        nav = []
        if page > 0:
            nav.append(InlineKeyboardButton(text="◀️", callback_data=f"nkct_{key}_{h}_{page - 1}"))
        nav.append(InlineKeyboardButton(text=f"{page + 1}/{pages}", callback_data="nknoop"))
        if page < pages - 1:
            nav.append(InlineKeyboardButton(text="▶️", callback_data=f"nkct_{key}_{h}_{page + 1}"))
        rows.append(nav)
        rows.append([InlineKeyboardButton(text="⬅️ Bo'limlar", callback_data=f"nkpl_{key}")])
        cat = items[0][1].get("category") or "Boshqa"
        await say(callback, f"📂 <b>{esc(cat)}</b>\n💵 Narx — 1000 tasi uchun (so'm)\n\nXizmatni tanlang 👇",
                  reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))

