    @dp.callback_query(F.data == "nkok")
    async def nk_confirm_cb(callback: CallbackQuery, state: FSMContext):
        if not await guard(callback):
            return
        d = await state.get_data()
        if not d.get("sid") or not d.get("link") or not d.get("qty"):
            await callback.answer("Ma'lumot eskirgan, qaytadan boshlang.", show_alert=True)
            return
        ok, msg, res = await place_order(callback.bot, callback.from_user.id, uname_of(callback.from_user),
                                         d["sid"], d["link"], int(d["qty"]))
        if not ok and msg == "LOW":
            missing = res - bal(callback.from_user.id)
            kb = InlineKeyboardMarkup(inline_keyboard=[[InlineKeyboardButton(text="➕ Hisob to'ldirish", callback_data="nktop")]])
            await say(callback, f"⚠️ <b>Balans yetarli emas!</b>\n\n💰 Narxi: {som(res)} so'm\n"
                                f"💳 Balansingiz: {som(bal(callback.from_user.id))} so'm\n📉 Yetishmaydi: <b>{som(missing)} so'm</b>",
                      reply_markup=kb)
            return
        if not ok:
            await state.clear()
            await say(callback, msg)
            return
        await state.clear()
        await say(callback, "✅ <b>Buyurtma qabul qilindi!</b>\n\n" + order_card(
            next(k for k, v in info["nk_orders"].items() if v is res), res)
                  + f"\n\n💳 Qolgan balans: {som(bal(callback.from_user.id))} so'm")

