    @dp.message(NkOrder.waiting_search, F.text)
    async def nk_search_in(message: Message, state: FSMContext):
        words = message.text.lower().split()
        res = []
        for sid, s in enabled_services().items():
            hay = f"{s['name']} {s.get('category', '')}".lower()
            if all(w in hay for w in words):
                res.append((sid, s))
        await state.clear()
        if not res:
            await message.answer("😔 Hech narsa topilmadi. Boshqa so'z bilan urinib ko'ring.")
            return
        res.sort(key=lambda x: price_1000(x[1]))
        rows = [[InlineKeyboardButton(text=f"{s['name'][:34]} — {som(price_1000(s))}", callback_data=f"nksv_{sid}")]
                for sid, s in res[:15]]
        await message.answer(f"🔍 Topildi: {len(res)} ta (eng arzon 15 tasi)", reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))

    # ---------------------------------------------------------------- buyurtmalar
    def my_orders(uid: int, limit: int = 10):
        mine = [(oid, o) for oid, o in info["nk_orders"].items() if o["uid"] == uid]
        mine.sort(key=lambda x: x[1]["created_at"], reverse=True)
        return mine[:limit]

    @dp.message(F.text == "📦 Buyurtmalarim")
    async def nk_my_orders(message: Message, state: FSMContext):
        await state.clear()
        if not await guard(message):
            return
        mine = my_orders(message.from_user.id)
        if not mine:
            await message.answer("📦 Sizda hali buyurtmalar yo'q. «🛍 Xizmatlar» orqali birinchi buyurtmangizni bering!")
            return
        lines = [f"{NK_STATUS_EMOJI.get(o['status'], '❔')} <b>#{oid}</b> — {esc(o['name'][:30])}\n"
                 f"   🔢 {o['qty']:,} · 💰 {som(o['price'])} so'm · {NK_STATUS_LABEL.get(o['status'], '')}" for oid, o in mine]
        btns = [InlineKeyboardButton(text=f"🔄 #{oid}", callback_data=f"nkst_{oid}") for oid, _ in mine]
        rows = [btns[i:i + 3] for i in range(0, len(btns), 3)]
        await message.answer("📦 <b>Oxirgi buyurtmalaringiz</b>\n\n" + "\n\n".join(lines) + "\n\nHolatni yangilash uchun tugmani bosing 👇",
                             reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))

    @dp.callback_query(F.data.startswith("nkst_"))
    async def nk_status_cb(callback: CallbackQuery):
        oid = callback.data[5:]
        o = info["nk_orders"].get(oid)
        if not o or (o["uid"] != callback.from_user.id and not is_admin(info, callback.from_user.id)):
            await callback.answer("Buyurtma topilmadi", show_alert=True)
            return
        if o.get("panel_id") and o["status"] in NK_ACTIVE:
            try:
                await refresh_order(oid, callback.bot)
            except Exception as e:
                logging.info(f"Nakrutka: holatni yangilashda xato: {e}")
        o = info["nk_orders"][oid]
        rows = []
        if o["status"] == "kutilmoqda" and not o.get("panel_id"):
            rows.append([InlineKeyboardButton(text="🚫 Buyurtmani bekor qilish", callback_data=f"nkcn_{oid}")])
        rows.append([InlineKeyboardButton(text="🔁 Qayta buyurtma", callback_data=f"nkre_{oid}")])
        await say(callback, order_card(oid, o), reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))

