    async def nk_user_cancel_cb(callback: CallbackQuery):
        oid = callback.data[5:]
        o = info["nk_orders"].get(oid)
        if not o or o["uid"] != callback.from_user.id:
            await callback.answer("Buyurtma topilmadi", show_alert=True)
