    async def mark_topup(callback: CallbackQuery, approve: bool):
        if not is_admin(info, callback.from_user.id):
            return
        tid = callback.data[5:]
        t = info["nk_topups"].get(tid)
        if not t:
            await callback.answer("So'rov topilmadi", show_alert=True)
            return
        if t["status"] != "kutilmoqda":
            await callback.answer("Bu so'rov allaqachon ko'rib chiqilgan.", show_alert=True)
            return
        t["status"] = "tasdiqlandi" if approve else "rad etildi"
        t["by"] = callback.from_user.id
        mark = "\n\n✅ <b>TASDIQLANDI</b>" if approve else "\n\n❌ <b>RAD ETILDI</b>"
        if approve:
            add_bal(t["uid"], t["amount"], "Hisob to'ldirish")
            st["topups"] += t["amount"]
            ref = info["nk_ref_by"].get(str(t["uid"]))
            if ref and int(S["ref_percent"]) > 0:
                bonus = int(t["amount"] * int(S["ref_percent"]) / 100)
                if bonus > 0:
                    add_bal(ref, bonus, "Referal bonusi")
                    info["nk_ref_earn"][str(ref)] = int(info["nk_ref_earn"].get(str(ref), 0)) + bonus
                    try:
                        await callback.bot.send_message(ref, f"🎁 Referalingiz hisobini to'ldirdi — sizga <b>{som(bonus)} so'm</b> bonus berildi!")
                    except Exception:
                        pass
            user_msg = f"✅ <b>Hisobingiz to'ldirildi!</b>\n\n➕ {som(t['amount'])} so'm\n💰 Balans: <b>{som(bal(t['uid']))} so'm</b>"
        else:
            user_msg = "❌ <b>To'lov so'rovingiz rad etildi.</b>\n\nMuammo bo'lsa, «📩 Murojaat» orqali yozing."
        save_data()
        try:
            await callback.bot.send_message(t["uid"], user_msg)
        except Exception:
            pass
        try:
            if callback.message.photo:
                await callback.message.edit_caption(caption=(callback.message.html_text or "") + mark)
            else:
                await callback.message.edit_text((callback.message.html_text or "") + mark)
        except Exception:
            pass
        await callback.answer("Bajarildi")

