    @dp.callback_query(F.data.startswith("nkset_"))
    async def nk_setting_pick(callback: CallbackQuery, state: FSMContext):
        if not is_admin(info, callback.from_user.id):
            return
        key = callback.data[6:]
        if key == "maintenance":
            S["maintenance"] = not S.get("maintenance")
            save_data()
            await callback.answer("Texnik rejim " + ("yoqildi" if S["maintenance"] else "o'chirildi"), show_alert=True)
            return
        if key in NK_SET_NUM:
            await state.set_state(NkAdm.set_value)
            await state.update_data(key=key)
            await callback.message.answer(f"{NK_SET_NUM[key]}\nJoriy qiymat: <b>{S[key]}</b>\n\nYangi qiymatni yozing:")
        elif key in NK_SET_TXT:
            await state.set_state(NkAdm.set_value)
            await state.update_data(key=key)
            await callback.message.answer(f"{NK_SET_TXT[key]}\n\nYangi matnni yozing (HTML mumkin). Standartga qaytarish uchun «-» yuboring:")
        await callback.answer()

    @dp.message(NkAdm.set_value, F.text)
    async def nk_setting_in(message: Message, state: FSMContext):
        if not is_admin(info, message.from_user.id):
            return
        d = await state.get_data()
        key = d.get("key")
        raw = message.text.strip()
        if key in NK_SET_NUM:
            try:
                v = float(raw.replace(" ", "").replace(",", ".")) if key == "markup" else int(raw.replace(" ", ""))
                assert v >= 0
                if key == "ref_percent":
                    assert v <= 100
                if key == "usd_rate":
                    assert v > 0
            except Exception:
                await message.answer("❌ To'g'ri qiymat kiriting.")
                return
            S[key] = v
        elif key in NK_SET_TXT:
            if raw == "-":
                S[key] = ""
            else:
                prob = _html_problem(raw)
                if prob:
                    await message.answer(f"❌ HTML xatosi: {prob}")
                    return
                S[key] = raw
        else:
            await state.clear()
            return
        save_data()
        await state.clear()
        await message.answer("✅ Saqlandi.")

