    @dp.message(NkAdm.bal_uid, F.text)
    async def nk_bal_uid_in(message: Message, state: FSMContext):
        try:
            uid = int(message.text.strip())
        except ValueError:
            await message.answer("❌ Faqat raqam (ID) kiriting.")
            return
        if uid not in info["users"]:
            await message.answer("❌ Bunday foydalanuvchi botdan foydalanmagan.")
            return
        await state.update_data(uid=uid)
        await state.set_state(NkAdm.bal_amount)
        await message.answer(f"💰 Joriy balans: {som(bal(uid))} so'm\nSummani yozing:")

    @dp.message(NkAdm.bal_amount, F.text)
    async def nk_bal_amount_in(message: Message, state: FSMContext):
        try:
            amount = int(message.text.strip().replace(" ", ""))
            assert amount > 0
        except Exception:
            await message.answer("❌ Musbat butun son kiriting.")
            return
        d = await state.get_data()
        uid = d["uid"]
        if d.get("mode") == "sub":
            amount = min(amount, bal(uid))
            add_bal(uid, -amount, "Admin tomonidan ayirildi")
            note = f"➖ Hisobingizdan {som(amount)} so'm ayirildi."
        else:
            add_bal(uid, amount, "Admin tomonidan qo'shildi")
            note = f"➕ Hisobingizga {som(amount)} so'm qo'shildi!"
        save_data()
        await state.clear()
        try:
            await message.bot.send_message(uid, f"{note}\n💰 Balans: <b>{som(bal(uid))} so'm</b>")
        except Exception:
            pass
        await message.answer(f"✅ Bajarildi. Yangi balans: {som(bal(uid))} so'm")

