    async def dl_stats(message: Message):
        if not staff(message):
            return
        st = info["stats"]
        today = dl_today()
        today_n = sum(1 for e in info["dl_log"] if e.get("at", "").startswith(today))
        ps = info.get("dl_plat_stats", {})
