def _botmenu_items():
    counts = {}
    for b in data["bots"].values():
        counts[b.get("type")] = counts.get(b.get("type"), 0) + 1
    items = []
    for bt, code_name in BOT_TYPES.items():
        if bt in MENU_HIDDEN_TYPES:
            continue
        entry = data["bot_menu"].get(bt)
        if entry is None:
            status = "pending"
        else:
            status = "on" if entry.get("enabled", True) else "off"
        items.append({
            "type": bt,
            "name": (entry.get("name") if entry else None) or code_name,
            "status": status,
            "bots": counts.get(bt, 0),
        })
    return items


async def api_admin_botmenu(request):
    if not is_admin_init_data(request.query.get("initData", "")):
        return _forbidden()
    return web.json_response({"items": _botmenu_items()}, headers=_NO_STORE_ADMIN)


async def _botmenu_action(request, action: str):
    body = await request.json()
    if not is_admin_init_data(body.get("initData", "")):
        return _forbidden()
    bt = body.get("type")
    if bt not in BOT_TYPES or bt in MENU_HIDDEN_TYPES:
        return web.json_response({"error": "invalid"}, status=400)
    menu = data["bot_menu"]
    if action == "add":
        if bt not in menu:
            menu[bt] = {"name": BOT_TYPES[bt], "enabled": True}  # nomi shu paytda bazaga muhrlanadi
    elif action == "toggle":
        if bt not in menu:
            return web.json_response({"error": "not_in_menu"}, status=400)
        menu[bt]["enabled"] = not menu[bt].get("enabled", True)
    elif action == "delete":
        menu.pop(bt, None)  # avval yaratilgan botlarga TEGILMAYDI
    save_data()
    return web.json_response({"ok": True, "items": _botmenu_items()}, headers=_NO_STORE_ADMIN)


async def api_admin_botmenu_add(request):
    return await _botmenu_action(request, "add")


async def api_admin_botmenu_toggle(request):
    return await _botmenu_action(request, "toggle")


async def api_admin_botmenu_delete(request):
    return await _botmenu_action(request, "delete")


async def api_admin_channels(request):
    if not is_admin_init_data(request.query.get("initData", "")):
        return _forbidden()
    items = []
    for cid, c in data["platform_channels"].items():
        ctype = c.get("type", "telegram")
        link = c.get("url") or c.get("username") or ""
        items.append({"id": cid, "title": c.get("title", ""), "emoji": SOCIAL_EMOJI.get(ctype, "📢"), "link": link})
    return web.json_response({"items": items}, headers=_NO_STORE_ADMIN)


async def api_admin_channel_add(request):
    body = await request.json()
    if not is_admin_init_data(body.get("initData", "")):
        return _forbidden()
    ctype = body.get("ctype") or "telegram"
    if ctype == "telegram":
        username = (body.get("username") or "").strip()
        if not username:
            return web.json_response({"error": "Kanal usernameni kiriting"}, status=400)
        try:
            chat = await main_bot.get_chat(username)
        except Exception as e:
            return web.json_response({"error": f"Kanal topilmadi: {e}"}, status=400)
        data["platform_channels"][str(chat.id)] = {"type": "telegram", "username": username, "title": chat.title}
        save_data()
        warning = ""
        try:
            me = await main_bot.get_me()
            member = await main_bot.get_chat_member(chat_id=chat.id, user_id=me.id)
            if member.status not in ("administrator", "creator"):
                warning = f"Bot \"{chat.title}\" kanalida ADMIN emas. Obuna tekshiruvi ishlashi uchun botni kanalga ADMIN qiling!"
        except Exception:
            warning = f"Bot \"{chat.title}\" kanalida ADMIN ekanligini tekshira olmadim. Botni kanalga ADMIN qiling!"
        return web.json_response({"ok": True, "warning": warning})
    title = (body.get("title") or "").strip()
    url = (body.get("url") or "").strip()
    if not (title and url):
        return web.json_response({"error": "Nom va havolani kiriting"}, status=400)
    if not (url.startswith("http://") or url.startswith("https://")):
        url = "https://" + url
    data["platform_channels"][f"social_{uuid.uuid4().hex[:8]}"] = {"type": ctype, "title": title, "url": url}
    save_data()
    return web.json_response({"ok": True, "warning": ""})


