# (regex, ruscha, inglizcha) — raqam/dinamik qismli matnlar
_I18N_RE = [
    (r"so'nggi (\d+) ta", r"последние \1", r"last \1"),
    (r"oxirgi (\d+) ta", r"последние \1", r"last \1"),
    (r"Oxirgi (\d+) ta kino", r"Последние \1 фильмов", r"Last \1 movies"),
    (r"TOP (\d+) kino", r"ТОП \1 фильмов", r"Top \1 movies"),
    (r"bo'yicha (\d+) ta natija:", r"— найдено: \1", r"— \1 results found:"),
    (r"Bu kontent hali chiqmagan\. Chiqish sanasi: ", r"Этот контент ещё не вышел. Дата выхода: ", r"This content hasn't been released yet. Release date: "),
    (r"</b> gacha \((\d+) kun qoldi\)", r"</b> (осталось дней: \1)", r"</b> (\1 days left)"),
    (r"</b> ta\b", r"</b>", r"</b>"),
    (r"va yana (\d+) ta", r"и ещё \1", r"and \1 more"),
    (r"\bKod (\w+)", r"Код \1", r"Code \1"),
    (r"Har bir do'st uchun <b>\+([^<]+)</b> bonus beriladi", r"За каждого друга вы получаете <b>+\1</b> бонус", r"You get a <b>+\1</b> bonus for every friend"),
    (r"Muddat: (\d+) kun", r"Срок: \1 дн.", r"Duration: \1 days"),
]


def _i18n_build():
    out = {}
    for li, lang in ((1, "ru"), (2, "en")):
        lit = {row[0]: row[li] for row in _I18N_LIT}
        keys = sorted(lit, key=len, reverse=True)
        lit_re = re.compile("|".join(re.escape(k) for k in keys))
        regs = [(re.compile(r[0]), r[li]) for r in _I18N_RE]
        out[lang] = (regs, lit_re, lit)
    return out


_I18N = _i18n_build()


def i18n_text(text, lang: str):
    """Obunachiga ko'rinadigan o'zbekcha matnni tanlangan tilga o'giradi (uz bo'lsa — o'zgarishsiz)."""
    pack = _I18N.get(lang)
    if not pack or not isinstance(text, str) or not text:
        return text
    regs, lit_re, lit = pack
    for rx, rep in regs:
        text = rx.sub(rep, text)
    return lit_re.sub(lambda m: lit[m.group(0)], text)


# Obunachining pastki (reply) menyusidagi tugmalar — ular bosilganda matn yana o'zbekchaga qaytariladi
KINO_REPLY_BUTTONS = [
    "🆕 Yangi kinolar", "🔥 TOP kinolar", "🏷 Kategoriyalar", "🏆 Reyting", "🎲 Tasodifiy kino", "🏷 Promokod",
    "💎 Premium", "👤 Profilim", "💎 VIP kinolar", "🔗 Do'st taklif qilish", "ℹ️ Yordam",
]


def _i18n_reverse() -> dict:
    rev = {}
    for uz in KINO_REPLY_BUTTONS:
        for lang in ("ru", "en"):
            t = i18n_text(uz, lang)
            if t != uz:
                rev[t] = uz
    return rev


KINO_I18N_REV = _i18n_reverse()


def _i18n_markup(mk, lang: str):
    try:
        if isinstance(mk, InlineKeyboardMarkup):
            rows, changed = [], False
            for row in mk.inline_keyboard:
                nr = []
                for b in row:
                    nt = i18n_text(b.text, lang)
                    if nt != b.text:
                        b = b.model_copy(update={"text": nt})
                        changed = True
                    nr.append(b)
                rows.append(nr)
            return InlineKeyboardMarkup(inline_keyboard=rows) if changed else mk
        if isinstance(mk, ReplyKeyboardMarkup):
            rows, changed = [], False
            for row in mk.keyboard:
                nr = []
                for b in row:
                    nt = i18n_text(b.text, lang)
                    if nt != b.text:
                        b = b.model_copy(update={"text": nt})
                        changed = True
                    nr.append(b)
                rows.append(nr)
            return mk.model_copy(update={"keyboard": rows}) if changed else mk
    except Exception as e:
        logging.info(f"Tugma tarjimasi xatosi (e'tiborsiz): {e}")
    return mk


async def kino_i18n_request_middleware(make_request, bot, method):
    """Kino bot (faqat obunachilarga ketadigan) xabarlarini tanlangan tilga o'giradi. Adminlarga — o'zbekcha."""
    try:
        info = data["bots"].get(bot.token)
        lang = (info or {}).get("language", "uz")
        if info and lang in ("ru", "en") and info.get("type") in KINO_TYPES:
            cid = getattr(method, "chat_id", None)
            is_staff = False
            if cid is not None:
                try:
                    is_staff = is_admin(info, cid) or cid in info.get("moderators", [])
                except Exception:
                    is_staff = False
            if not is_staff:
                upd = {}
                for f in ("text", "caption"):
                    v = getattr(method, f, None)
                    if isinstance(v, str):
                        nv = i18n_text(v, lang)
                        if nv != v:
                            upd[f] = nv
                mk = getattr(method, "reply_markup", None)
                if mk is not None:
                    nm = _i18n_markup(mk, lang)
                    if nm is not mk:
                        upd["reply_markup"] = nm
                if upd:
                    method = method.model_copy(update=upd)
    except Exception as e:
        logging.info(f"Kino tarjima middleware xatosi (e'tiborsiz): {e}")
    return await make_request(bot, method)
