# ================= 🎬 MEDIA BOT TURI: tugma va matnlarni turga moslash =================
# Ichki kod bir xil («kino» so'zlari bilan) qoladi; bot YUBORAYOTGAN tugma/matnlar tanlangan turga qarab o'zgaradi
# (masalan Anime botda «🆕 Yangi kinolar» -> «🆕 Yangi animelar»). Bosilgan tugma matni qabul qilinganda asliga qaytariladi.
_KIND_WORD_RE = re.compile(r"\b(kino|film)", re.I)


def kind_label(text, kind: str):
    k = MEDIA_KINDS.get(kind)
    if not k or kind == "kino" or not isinstance(text, str) or not text:
        return text
    root = k["root"]

    def rp(m):
        w = m.group(0)
        if len(w) > 1 and w.isupper():
            return root.upper()
        return root[0].upper() + root[1:] if w[0].isupper() else root
    return _KIND_WORD_RE.sub(rp, text).replace("🎬", k["emoji"])


def kind_text(text, kind: str):
    """Faqat ma'lum tayyor matnlar almashtiriladi (admin yozgan tavsif/sarlavhalarga tegilmaydi)."""
    k = MEDIA_KINDS.get(kind)
    if not k or kind == "kino" or not isinstance(text, str):
        return text
    return text.replace("Film kodini yuboring, men uni topib beraman.",
                        k["welcome"].split(" ", 1)[-1])


def _kind_markup(info: dict, mk, kind: str):
    try:
        if isinstance(mk, ReplyKeyboardMarkup):
            rev = info.setdefault("kind_rev", {})
            rows, changed, dirty = [], False, False
            for row in mk.keyboard:
                nr = []
                for b in row:
                    nt = kind_label(b.text, kind)
                    if nt != b.text:
                        if rev.get(nt) != b.text and len(rev) < 400:
                            rev[nt] = b.text
                            dirty = True
                        b = b.model_copy(update={"text": nt})
                        changed = True
                    nr.append(b)
                rows.append(nr)
            if dirty:
                save_data()
            return mk.model_copy(update={"keyboard": rows}) if changed else mk
        if isinstance(mk, InlineKeyboardMarkup):
            rows, changed = [], False
            for row in mk.inline_keyboard:
                nr = []
                for b in row:
                    nt = kind_label(b.text, kind)
                    if nt != b.text:
                        b = b.model_copy(update={"text": nt})
                        changed = True
                    nr.append(b)
                rows.append(nr)
            return InlineKeyboardMarkup(inline_keyboard=rows) if changed else mk
    except Exception as e:
        logging.info(f"Media tur tugmalari xatosi (e'tiborsiz): {e}")
    return mk


async def media_kind_request_middleware(make_request, bot, method):
    try:
        info = data["bots"].get(bot.token)
        kind = media_kind_of(info) if info else "kino"
        if info and kind != "kino" and info.get("language", "uz") == "uz":
            upd = {}
            mk = getattr(method, "reply_markup", None)
            if mk is not None:
                nm = _kind_markup(info, mk, kind)
                if nm is not mk:
                    upd["reply_markup"] = nm
            for f in ("text", "caption"):
                v = getattr(method, f, None)
                if isinstance(v, str):
                    nv = kind_text(v, kind)
                    if nv != v:
                        upd[f] = nv
            if upd:
                method = method.model_copy(update=upd)
    except Exception as e:
        logging.info(f"Media tur middleware xatosi (e'tiborsiz): {e}")
    return await make_request(bot, method)
# ================= /MEDIA BOT TURI =================


# ================= 🎨 KINO BOT TUGMA RANGLARI =================
# Har bir kino botning o'z sozlamasi: info["btn_colors"] (tugma matni -> rang), info["btn_default_color"]
# (hamma tugmalar uchun umumiy rang) va info["btn_seen"] (bot yuborgan tugmalar ro'yxati).
def kino_style_markup(info: dict, mk):
    """Tugmalarni ro'yxatga oladi va sozlangan ranglarni qo'llaydi. O'zgarish bo'lmasa None qaytaradi."""
    colors = info.get("btn_colors") or {}
    default = info.get("btn_default_color")
    seen = info.setdefault("btn_seen", [])
    changed = False

    def restyle(b):
        nonlocal changed
        text = getattr(b, "text", None)
        key = _btn_key(text) if text else ""
        cbd = str(getattr(b, "callback_data", "") or "")
        if not key or cbd.startswith("kclr_"):
            return b
        _btn_seen_add(key, seen)
        style = _btn_style_for(key, colors) or auto_btn_style(b) or default or AUTO_DEFAULT_STYLE
        if style and not getattr(b, "style", None):
            changed = True
            return b.model_copy(update={"style": style})
        return b

    if isinstance(mk, InlineKeyboardMarkup):
        rows = [[restyle(b) for b in row] for row in mk.inline_keyboard]
        del seen[300:]
        return mk.model_copy(update={"inline_keyboard": rows}) if changed else None
    if isinstance(mk, ReplyKeyboardMarkup):
        rows = [[restyle(b) for b in row] for row in mk.keyboard]
        del seen[300:]
        return mk.model_copy(update={"keyboard": rows}) if changed else None
    return None


async def kino_cover_middleware(make_request, bot, method):
    """Kino videosi file_id bilan yuborilganda, unga biriktirilgan cover rasmini (video ko'rinishi) qo'shadi.
    Telegram rad etsa — covers'iz yuboradi."""
    try:
        if getattr(method, "__api_method__", "") == "sendVideo" and not getattr(method, "cover", None):
            info = data["bots"].get(bot.token)
            vid = getattr(method, "video", None)
            cid = ((info or {}).get("video_covers") or {}).get(vid) if isinstance(vid, str) else None
            if cid:
                try:
                    return await make_request(bot, method.model_copy(update={"cover": cid}))
                except TelegramBadRequest as e:
                    if "not modified" in str(e).lower():
                        raise
                    logging.warning(f"Cover qabul qilinmadi, covers'iz yuborilmoqda: {e}")
    except TelegramBadRequest:
        raise
    except Exception as e:
        logging.info(f"Cover xatosi (e'tiborsiz): {e}")
    return await make_request(bot, method)


async def kino_btn_style_middleware(make_request, bot, method):
    """Kino bot xabarlaridagi tugmalarga rang beradi. Telegram rad etsa — asl (rangsiz) ko'rinishda yuboradi."""
    styled = None
    try:
        info = data["bots"].get(bot.token)
        mk = getattr(method, "reply_markup", None)
        if info and info.get("type") in KINO_TYPES and isinstance(mk, (InlineKeyboardMarkup, ReplyKeyboardMarkup)):
            new_mk = kino_style_markup(info, mk)
            if new_mk is not None:
                styled = method.model_copy(update={"reply_markup": new_mk})
    except Exception as e:
        logging.info(f"Kino tugma ranglari xatosi (e'tiborsiz): {e}")
    if styled is not None:
        try:
            return await make_request(bot, styled)
        except TelegramBadRequest as e:
            if "not modified" in str(e).lower():
                raise
            logging.warning(f"Rangli tugmalar qabul qilinmadi, oddiy ko'rinishda yuborilmoqda: {e}")
    return await make_request(bot, method)
# ================= /KINO TUGMA RANGLARI =================


def get_kinopanel_url(bot_id) -> str:
    """Kino bot paneli URL'i: https://<domen>/kinopanel?b=<bot_id>"""
    if bot_id is None:
        return ""
    explicit = os.getenv("MINIAPP_URL")
    if explicit:
        base = explicit.rstrip("/")
    else:
        domain = os.getenv("RAILWAY_PUBLIC_DOMAIN")
        if not domain:
            return ""
        base = f"https://{domain}"
    return f"{base}/kinopanel?b={bot_id}"


def get_kinoweb_url(bot_id) -> str:
    """Xalq uchun ochiq veb kino sahifasi: https://<domen>/kino?b=<bot_id>"""
    purl = get_kinopanel_url(bot_id)
    return purl.replace("/kinopanel?", "/kino?") if purl else ""


KINO_WEB_MIN_DESC = 30   # veb panelga qo'shish uchun tavsifning eng kam uzunligi (belgi)


def kino_web_missing(m: dict) -> list:
    """Filmni veb panelga qo'yish uchun yetishmayotgan narsalar: cover, desc (to'liq tavsif), video."""
    miss = []
    if not m.get("cover"):
        miss.append("cover")
    if len((m.get("desc") or "").strip()) < KINO_WEB_MIN_DESC:
        miss.append("desc")
    if not (m.get("file_id") or m.get("episodes")):
        miss.append("video")
    return miss


def kw_visible(m: dict) -> bool:
    """Film xalqqa veb sahifada ko'rinadimi: veb belgisi bor, cover+tavsif+video to'liq, chiqish sanasi kelgan."""
    if not m or not m.get("web") or m.get("pending_announce") or kino_web_missing(m):
        return False
    ra = m.get("release_at")
    if ra:
        try:
            if datetime.fromisoformat(ra) > datetime.now():
                return False
        except Exception:
            pass
    return True


def _kino_today() -> str:
    return datetime.now().strftime("%Y-%m-%d")


def _kino_count_view(info: dict):
    """Kunlik ko'rishlar hisobini yuritadi (panel grafigi uchun)."""
    dv = info.setdefault("daily_views", {})
    today = _kino_today()
    dv[today] = dv.get(today, 0) + 1
    vh = info.setdefault("views_hourly", {})      # statistika uchun: oxirgi 24 soat aniq hisoblanadi
    hk = datetime.now().strftime("%Y-%m-%d %H")
    vh[hk] = vh.get(hk, 0) + 1
    if len(vh) > 800:
        for k in sorted(vh.keys())[:-720]:
            vh.pop(k, None)
    if len(dv) > 60:
        for k in sorted(dv.keys())[:-45]:
            dv.pop(k, None)


