KINO_POST_DELIVER = {}      # {token: post_deliver} — setup_kino_bot ro'yxatga oladi
KINO_WATCH = {}             # {token: async fn(uid, code) -> natija} — mini appdagi «Filmni ko'rish» tugmasi


def kino_now() -> datetime:
    """Toshkent vaqti (UTC+5), tzsiz."""
    return datetime.now(timezone(timedelta(hours=5))).replace(tzinfo=None)


def kino_log_view(info: dict, uid, code, ep=None):
    """Kim qaysi kinoni ko'rganini yozib boradi (statistika, reyting va «kim nimani ko'rgan» uchun)."""
    try:
        ts = kino_now()
        log = info.setdefault("view_log", [])
        log.append([int(uid), str(code), ts.strftime("%Y-%m-%d %H:%M"), int(ep or 0)])
        if len(log) > 3000:
            del log[:len(log) - 2500]
        cd = info.setdefault("code_day", {})
        d = cd.setdefault(ts.strftime("%Y-%m-%d"), {})
        d[str(code)] = d.get(str(code), 0) + 1
        if len(cd) > 16:
            for k in sorted(cd)[:-14]:
                cd.pop(k, None)
        uv = info.setdefault("user_views", {}).setdefault(str(uid), {})
        uv[str(code)] = uv.get(str(code), 0) + 1
    except Exception as e:
        logging.info(f"kino_log_view xatosi (e'tiborsiz): {e}")


def kino_rating(info: dict, days: int) -> list:
    """Oxirgi `days` kun (1 = bugun) bo'yicha [(kod, ko'rishlar)] — kamayish tartibida."""
    since = (kino_now() - timedelta(days=days - 1)).strftime("%Y-%m-%d")
    agg = {}
    for day, m in (info.get("code_day") or {}).items():
        if day >= since:
            for c, n in m.items():
                agg[c] = agg.get(c, 0) + n
    return sorted(agg.items(), key=lambda x: -x[1])


KPROMO_SCOPES = {"all": "Hammasiga", "premium": "Faqat Premium", "movie": "Faqat pullik kino"}


def kpromo_percent(info: dict, uid, kind: str) -> int:
    """Foydalanuvchining faol promokodi bo'yicha chegirma foizi (kind: 'premium' yoki 'movie')."""
    try:
        d = (info.get("kpromo_user") or {}).get(str(uid))
        if not d:
            return 0
        p = (info.get("kpromos") or {}).get(d.get("code"))
        if not p or not p.get("active", True) or p.get("scope", "all") not in ("all", kind):
            return 0
        if int(uid) in p.get("used_by", []):
            return 0
        mu = int(p.get("max_uses", 0) or 0)
        if mu and len(p.get("used_by", [])) >= mu:
            return 0
        return max(0, min(90, int(p.get("percent", 0))))
    except Exception:
        return 0


def kpromo_price(info: dict, uid, base, kind: str) -> int:
    base = int(base)
    pc = kpromo_percent(info, uid, kind)
    if pc <= 0:
        return base
    return max(1, int(round(base * (100 - pc) / 100.0)))


def kpromo_consume(info: dict, uid, kind: str):
    """To'lov muvaffaqiyatli bo'lganda promokodni ishlatilgan deb belgilaydi."""
    try:
        if kpromo_percent(info, uid, kind) <= 0:
            return
        d = (info.get("kpromo_user") or {}).pop(str(uid), None)
        p = (info.get("kpromos") or {}).get((d or {}).get("code"))
        if p is not None and int(uid) not in p.setdefault("used_by", []):
            p["used_by"].append(int(uid))
    except Exception as e:
        logging.info(f"kpromo_consume xatosi (e'tiborsiz): {e}")


def premium_saving_pct(info: dict, tid: str) -> int:
    """Uzoq tarif eng qisqa tarifga nisbatan necha foiz tejaydi."""
    try:
        ts = info.get("premium_tariffs") or {}
        t = ts[tid]
        base = min(ts.values(), key=lambda x: int(x["days"]))
        if int(t["days"]) <= int(base["days"]):
            return 0
        pct = round(100 - (t["price"] / t["days"]) / (base["price"] / base["days"]) * 100)
        return pct if pct >= 5 else 0
    except Exception:
        return 0


def kino_parse_when(raw: str):
    """«2026-10-15 18:30», «15.10.2026 18:30», «bugun 18:30», «ertaga 09:00», «18:30» -> datetime yoki None."""
    t = (raw or "").strip().lower().replace("'", "").replace("ʻ", "").replace("’", "")
    now = kino_now()
    m = re.search(r"(\d{1,2})[:.](\d{2})\s*$", t)
    if not m:
        return None
    hh, mm = int(m.group(1)), int(m.group(2))
    if hh > 23 or mm > 59:
        return None
    head = t[:m.start()].strip()
    try:
        if head in ("", "bugun"):
            d = now.date()
        elif head == "ertaga":
            d = (now + timedelta(days=1)).date()
        elif re.fullmatch(r"\d{4}-\d{1,2}-\d{1,2}", head):
            y, mo, da = (int(x) for x in head.split("-"))
            d = datetime(y, mo, da).date()
        elif re.fullmatch(r"\d{1,2}\.\d{1,2}\.\d{4}", head):
            da, mo, y = (int(x) for x in head.split("."))
            d = datetime(y, mo, da).date()
        else:
            return None
        return datetime(d.year, d.month, d.day, hh, mm)
    except ValueError:
        return None


async def kino_sched_post_loop():
    """Har 30 soniyada: vaqti kelgan rejalashtirilgan postlarni kanalga yuboradi."""
    while True:
        try:
            now = kino_now()
            for token, info in list(data["bots"].items()):
                if info.get("type") not in KINO_TYPES:
                    continue
                lst = info.get("scheduled_posts") or []
                due = [p for p in lst if p.get("status") == "pending" and p.get("at", "9") <= now.strftime("%Y-%m-%d %H:%M")]
                if not due:
                    continue
                deliver = KINO_POST_DELIVER.get(token)
                for p in due:
                    p["status"] = "sending"
                    save_data()
                    err = ""
                    try:
                        if not deliver:
                            raise RuntimeError("bot hali ishga tushmagan")
                        await deliver(p["chat"] if str(p["chat"]) == "bot" else int(p["chat"]), p["post"])
                        p["status"] = "sent"
                    except Exception as e:
                        p["status"] = "failed"
                        err = str(e)[:150]
                        logging.warning(f"Rejalashtirilgan post yuborilmadi ({token[-6:]}): {e}")
                    p["done_at"] = now.strftime("%Y-%m-%d %H:%M")
                    save_data()
                    try:
                        if p["status"] == "sent":
                            txt = f"⏰ Rejalashtirilgan post «{html_escape(p.get('title') or '')}» yuborildi ✅"
                        else:
                            txt = (f"⚠️ Rejalashtirilgan post «{html_escape(p.get('title') or '')}» yuborilmadi.\n"
                                   f"Kanalga bo'lsa, bot kanalda admin ekanini tekshiring.\n<i>{html_escape(err)}</i>")
                        await main_bot.send_message(info["admin_id"], txt)
                    except Exception:
                        pass
                if len(lst) > 40:
                    keep = [p for p in lst if p.get("status") in ("pending", "sending")]
                    done = [p for p in lst if p.get("status") not in ("pending", "sending")][-15:]
                    info["scheduled_posts"] = keep + done
                    save_data()
        except Exception as e:
            logging.error(f"kino_sched_post_loop xatosi: {e}")
        await asyncio.sleep(30)
