async def kw_api_cover(request):
    token, info, err = kw_find(request)
    if err:
        return err
    m = info.get("movies", {}).get(request.query.get("code", ""))
    if not kw_visible(m):
        return web.Response(status=404)
    cid = m.get("cover")
    hit = _KW_COVER_CACHE.get(cid)
    if hit is None:
        path = await kw_tg_path(token, cid)
        if not path:
            return web.Response(status=404)
        try:
            async with httpx.AsyncClient(timeout=30) as c:
                r = await c.get(f"https://api.telegram.org/file/bot{token}/{path}")
        except Exception:
            return web.Response(status=502)
        if r.status_code != 200:
            return web.Response(status=404)
        ctype = "image/png" if path.lower().endswith(".png") else "image/webp" if path.lower().endswith(".webp") else "image/jpeg"
        hit = (r.content, ctype)
        _KW_COVER_CACHE[cid] = hit
        while len(_KW_COVER_CACHE) > 80:
            _KW_COVER_CACHE.popitem(last=False)
    return web.Response(body=hit[0], content_type=hit[1], headers={"Cache-Control": "public, max-age=3600"})


async def kw_api_video(request):
    """Bepul filmni brauzerga oqim (Range bilan) qilib uzatadi. Pullik/VIP film bu yerda ochilmaydi."""
    token, info, err = kw_find(request)
    if err:
        return err
    code = request.query.get("code", "")
    m = info.get("movies", {}).get(code)
    if not kw_visible(m):
        return web.json_response({"error": "not_found"}, status=404, headers=_NO_STORE)
    if kw_access(info, code, m) != "free":
        return web.json_response({"error": "locked"}, status=403, headers=_NO_STORE)
    if m.get("type") == "series":
        fid = (m.get("episodes") or {}).get(str(request.query.get("ep") or "1"))
    else:
        fid = m.get("file_id")
    if not isinstance(fid, str):
        return web.json_response({"error": "not_found"}, status=404, headers=_NO_STORE)
    path = await kw_tg_path(token, fid)
    if not path:
        # Telegram Bot API 20 MB dan katta faylni bermaydi — sahifa foydalanuvchini botga yo'naltiradi
        return web.json_response({"error": "too_big"}, status=413, headers=_NO_STORE)
    rng = (request.headers.get("Range") or "").replace(" ", "")
    up_headers = {"Range": rng} if rng else {}
    client = httpx.AsyncClient(timeout=httpx.Timeout(30, read=90))
    try:
        req = client.build_request("GET", f"https://api.telegram.org/file/bot{token}/{path}", headers=up_headers)
        r = await client.send(req, stream=True)
    except Exception:
        await client.aclose()
        return web.json_response({"error": "upstream"}, status=502, headers=_NO_STORE)
    if r.status_code not in (200, 206):
        await r.aclose()
        await client.aclose()
        return web.json_response({"error": "upstream"}, status=502, headers=_NO_STORE)
    if not rng or rng == "bytes=0-":
        try:   # har bir ko'rish bir marta hisoblanadi (probe "bytes=0-0" hisoblanmaydi)
            info.setdefault("request_counts", {})[code] = info.get("request_counts", {}).get(code, 0) + 1
            _kino_count_view(info)
            save_data()
        except Exception:
            pass
    out = {"Content-Type": "video/mp4", "Cache-Control": "private, max-age=3600",
           "Accept-Ranges": r.headers.get("Accept-Ranges", "bytes" if r.status_code == 206 else "none")}
    for h in ("Content-Length", "Content-Range"):
        if h in r.headers:
            out[h] = r.headers[h]
    resp = web.StreamResponse(status=r.status_code, headers=out)
    try:
        await resp.prepare(request)
        async for chunk in r.aiter_bytes(65536):
            await resp.write(chunk)
    except (ConnectionResetError, ConnectionError):
        pass
    finally:
        await r.aclose()
        await client.aclose()
    return resp


async def kw_api_watch(request):
    token, info, err = kw_find(request)
    if err:
        return err
    try:
        body = await request.json()
        if not isinstance(body, dict):
            body = {}
    except Exception:
        body = {}
    parsed = validate_webapp_init_data(str(body.get("initData", "")), token)
    if not parsed:
        return web.json_response({"error": "invalid_init_data"}, status=401, headers=_NO_STORE)
    try:
        uid = int(json.loads(parsed.get("user", "{}")).get("id"))
    except Exception:
        return web.json_response({"error": "no_user"}, status=400, headers=_NO_STORE)
    code = str(body.get("code", ""))
    if not kw_visible(info.get("movies", {}).get(code)):
        return web.json_response({"error": "not_found"}, status=404, headers=_NO_STORE)
    fn = KINO_WATCH.get(token)
    if not fn:
        return web.json_response({"error": "unavailable"}, status=503, headers=_NO_STORE)
    if not _pub_rate(token, uid, "watch", 5, 30):
        return web.json_response({"result": "slow"}, headers=_NO_STORE)
    return web.json_response({"result": await fn(uid, code)}, headers=_NO_STORE)


